export function inferSetZone(set, sectionKey) {
      if (!set) return "aerobic";
      const text = `${set.desc || ""} ${set.focus || ""}`.toLowerCase();

      // Cooldowns are always easy unless desc says otherwise.
      if (sectionKey === "cooldown") {
        if (/sprint|fast|hard|all.?out|race/.test(text)) return "aerobic";
        return "easy";
      }

      // Strong keyword cues — explicit intensity language wins over heuristics.
      if (/all.?out|sprint|max(?!imum aerobic)|blast|empty the tank|top speed|race pace/.test(text)) {
        return "anaerobic";
      }
      if (/vo2|fast effort|fast,? hold|fast finish|fast close|fast,? fatigued/.test(text)) {
        return "vo2";
      }
      if (/threshold|t.?pace|rpe ?[78]/.test(text)) return "threshold";
      // S4 #11 — keyword set is tighter for main than for warmup/drill. In a main
      // set, "drill rotation" or "stroke technique" is often a sub-cue of a
      // harder workout (e.g. "Pull with paddles + drill rotation") and shouldn't
      // collapse the whole set to easy/aerobic. Keep those words for warmup/drill
      // sections where they genuinely signal easy work.
      const isWarmupOrDrill = (sectionKey === "warmup" || sectionKey === "drill");
      const easyRegex = isWarmupOrDrill
        ? /easy|recovery|smooth|drill|technique/
        : /easy|recovery|smooth/;
      if (easyRegex.test(text)) {
        return isWarmupOrDrill ? "easy" : "aerobic";
      }
      if (/descend|build|negative.?split|strong/.test(text)) {
        // Descend/build sets typically climb into threshold by the end.
        return "threshold";
      }
      if (/moderate|steady|aerobic/.test(text)) return "aerobic";

      // Interval-tightness fallback: estimate seconds/100yd then bucket.
      // Tighter intervals = higher zone. This is a coarse signal.
      const secs = parseIntervalSecs(set.interval);
      const dist = Number(set.dist || 0);
      if (secs && dist > 0) {
        const per100 = secs / (dist / 100);
        // S4 #13 — Stroke factor: non-free strokes naturally have higher
        // per-100 at the same effort, so the thresholds need to scale up or
        // a "moderate" back/breast gets tagged harder than a "moderate" free.
        // Heuristic detection from desc text; defaults to free (1.0) when unclear.
        const strokeFactor =
          /\bback/.test(text)                ? 1.09 :
          /\bbreast/.test(text)              ? 1.18 :
          /\bbutterfly\b|\bfly\b/.test(text) ? 1.05 :
          /\bim\b/.test(text)                ? 1.13 :
          1.0;
        // Cutoffs MUST stay monotonic (anaerobicMax < vo2Max < thresholdMax <
        // aerobicMax) or a band gets swallowed. Short reps (dist ≤ 50) run at
        // tighter per-100 send-offs, so the whole ladder shifts faster — but
        // both anaerobic AND vo2 must shift together.
        // BUG FIX (VO2 gap): the old ≤50 values were anaerobicMax 110 / vo2Max
        // 95 — inverted, so `per100 < 110 → anaerobic` ate the entire 95–110
        // vo2 band and a 50 could NEVER classify as vo2. Now ≤50 keeps real
        // sprints anaerobic (per100 < 90) and opens a vo2 band 90–110, so a
        // hard 50 (e.g. 0:52 send-off, per100 104) reads vo2 instead of being
        // over-promoted to anaerobic.
        const anaerobicMax = (dist <= 50 ? 90  : 75)  * strokeFactor;
        const vo2Max       = (dist <= 50 ? 110 : 95)  * strokeFactor;
        const thresholdMax = (dist <= 50 ? 125 : 115) * strokeFactor;
        const aerobicMax   = 145 * strokeFactor;
        if (per100 < anaerobicMax) return "anaerobic";
        if (per100 < vo2Max)       return "vo2";
        if (per100 < thresholdMax) return "threshold";
        if (per100 < aerobicMax)   return "aerobic";
        return "easy";
      }

      // Section-default fallback when text gives no signal.
      if (sectionKey === "warmup")   return "easy";
      if (sectionKey === "drill")    return "aerobic";
      if (sectionKey === "cooldown") return "easy";
      return "aerobic";
    }

export function inferBlockZone(block) {
      if (!block) return "aerobic";
      if (block.primary_zone && ZONES[block.primary_zone]) return block.primary_zone;
      const sets = Array.isArray(block.sets) ? block.sets : [];
      if (!sets.length) return "aerobic";
      // For warmup/cooldown, take the modal (most common) zone since they're
      // typically uniform and a single accent set shouldn't redefine the block.
      // For drill/main, take the *dominant by yardage* zone.
      const tally = {};
      for (const s of sets) {
        const z = s.zone || inferSetZone(s, block.section);
        const w = (s.reps || 1) * (s.dist || 0);
        tally[z] = (tally[z] || 0) + Math.max(1, w);
      }
      let best = null, bestW = -1;
      for (const [z, w] of Object.entries(tally)) {
        if (w > bestW) { best = z; bestW = w; }
      }
      return best || "aerobic";
    }

