export const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];

export function pickWeighted(arr, weightFn) {
      const weights = arr.map(weightFn);
      const total = weights.reduce((s, w) => s + (w > 0 ? w : 0), 0);
      if (total <= 0) {
        // S4 #10 — defensive guard: if the weight function zeroed everything
        // (e.g. phase × recovery filter collapsed every option's score), we
        // fall back to uniform pick. That's a safe degradation but masks an
        // upstream bug where the filter should have left at least one option
        // with positive weight. Surface it in the console so the issue is
        // visible during development.
        if (typeof console !== "undefined" && console.warn) {
          console.warn("[pickWeighted] all weights non-positive — falling back to uniform pick", { arrLen: arr.length });
        }
        return pick(arr);
      }
      let r = Math.random() * total;
      for (let i = 0; i < arr.length; i++) {
        const w = weights[i] > 0 ? weights[i] : 0;
        r -= w;
        // Strict `<` so each weight gets a half-open interval [a, b). The old
        // `<=` boundary biased toward index 0 when r landed exactly at 0 after
        // subtracting the first weight — measurable only for integer weights
        // (e.g. [1,1,1] gave arr[0] a slight edge at r=1.0 exactly).
        if (r < 0) return arr[i];
      }
      return arr[arr.length - 1];
    }

export const MIN_YARDS  = 1900;

export const MIN_METERS = 2000;

export const EQUIP_REQUIREMENTS = {
      kickboard: ["kick", "kickPart"],
      fins:      ["kick", "kickPart", "underkick"],
      paddles:   ["pull"],
      pullBuoy:  ["pull"],
      snorkel:   ["snorkel"],
    };

export function equipMode(equipment, k) {
      if (!equipment) return "off";
      const v = equipment[k];
      if (v === "required" || v === true)  return "required";
      if (v === "preferred")               return "preferred";
      return "off";
    }

export function isEquipRequired(equipment, k) { return equipMode(equipment, k) === "required"; }

export function isEquipPreferred(equipment, k){ return equipMode(equipment, k) === "preferred"; }

export function eqTagsIn(option) {
      return new Set(option.sets.filter(s => s.eq).map(s => s.eq));
    }

export function combinationSatisfies(dr, ma, equipment) {
      if (!equipment) return true;
      const tags = new Set([...eqTagsIn(dr), ...eqTagsIn(ma)]);
      for (const k of Object.keys(EQUIP_REQUIREMENTS)) {
        if (isEquipRequired(equipment, k) && !EQUIP_REQUIREMENTS[k].some(t => tags.has(t))) return false;
      }
      return true;
    }

export function preferredEquipMatches(option, equipment) {
      if (!equipment || !option || !option.sets) return 0;
      const tags = eqTagsIn(option);
      let n = 0;
      for (const k of Object.keys(EQUIP_REQUIREMENTS)) {
        if (!isEquipPreferred(equipment, k)) continue;
        if (EQUIP_REQUIREMENTS[k].some(t => tags.has(t))) n += 1;
      }
      return n;
    }

