export function generateEngineForSection(section, typeId, budgetYd, recent, engineDisfavorites, disfavorMode, engineFavorites, lanesPaceSecs, activeConstraints = []) {
      if (typeof TEMPLATE_ENGINE === "undefined") return { option: null };
      const applicable = TEMPLATE_ENGINE.applicable(section, typeId);
      if (!applicable.length) return { option: null };
      // v1.3 + v1.8 + v1.13 — weighted pick.
      //   Favorite (template_id, stroke) → 3× weight (UNIVERSAL precedence:
      //     favorite wins over disfavor when both apply to same tuple).
      //   Disfavored (template_id, stroke) → disfavorMultiplier (0.25 in
      //     downweight mode, 0 in exclude mode) — IF not also favorited.
      //   If all weights collapse to zero, fall back to uniform random.
      const stroke = templateDefaultStroke(typeId);
      const favSet = new Set((engineFavorites    || []).map(f => `${f.template_id}:${f.stroke}`));
      const disSet = new Set((engineDisfavorites || []).map(d => `${d.template_id}:${d.stroke}`));
      const disfavorMultiplier = disfavorMode === "exclude" ? 0 : 0.25;
      const weights = applicable.map(t => {
        const k = `${t.id}:${stroke}`;
        if (favSet.has(k)) return 3;                  // v1.13: favorite wins
        if (disSet.has(k)) return disfavorMultiplier; // disfavor downweight
        return 1;
      });
      const totalW = weights.reduce((s, w) => s + w, 0);
      let tpl;
      if (totalW <= 0) {
        tpl = applicable[Math.floor(Math.random() * applicable.length)];
      } else {
        let r = Math.random() * totalW;
        let pickIdx = applicable.length - 1;
        for (let i = 0; i < applicable.length; i++) {
          r -= weights[i];
          if (r < 0) { pickIdx = i; break; }
        }
        tpl = applicable[pickIdx];
      }
      return TEMPLATE_ENGINE.generateWithRetry({
        templateId: tpl.id, typeKey: typeId, section, budgetYd, recent: recent || [], lanesPaceSecs, activeConstraints,
      });
    }

export function applyEngineOverrides(typeId, sections, sources, recent, engineDisfavorites, disfavorMode, engineFavorites, lanesPaceSecs, activeConstraints = []) {
      if (!sources) return sections;
      const out = { ...sections };
      // kick is bank-only (sources never names it from the UI), so its
      // `sources[sect] || "bank"` short-circuits to bank → no override.
      // Listed here only so a future kick-source would route generically;
      // generateEngineForSection degrades to { option: null } for sections
      // with no applicable template, so an unknown source can't throw.
      for (const sect of ["warmup", "drill", "kick", "main", "cooldown"]) {
        const src = sources[sect] || "bank";
        if (src === "engine") {
          const original = sections[sect];
          if (!original || !original.totalYards) continue;
          const res = generateEngineForSection(sect, typeId, original.totalYards, recent, engineDisfavorites, disfavorMode, engineFavorites, lanesPaceSecs, activeConstraints);
          if (res && res.option) {
            out[sect] = {
              ...res.option,
              __engineMeta: {
                template_id: res.templateUsed,
                stroke: templateDefaultStroke(typeId),
              },
            };
          }
          // else: engine had no applicable template or all attempts failed —
          // silent bank fallback (original section stays unchanged)
        } else if (src === "mix") {
          // Mix: bank prefix + engine suffix, two parented sub-blocks under
          // one section header (per spec §7.3). Engine sub-block sized at
          // ~50% of the bank prefix's totalYards. Total section yards =
          // bank + engine, which exceeds the picker's per-section
          // allocation; documented as known limitation (mix is opt-in
          // extra variety, not a strict budget mode).
          const original = sections[sect];
          if (!original || !original.totalYards) continue;
          const engineBudget = Math.max(100, Math.round(original.totalYards * 0.5));
          const res = generateEngineForSection(sect, typeId, engineBudget, recent, engineDisfavorites, disfavorMode, engineFavorites, lanesPaceSecs, activeConstraints);
          if (res && res.option) {
            const stroke = templateDefaultStroke(typeId);
            out[sect] = {
              // Note: deliberately omit `section` so buildWorkout's
              // hardcoded section value applies (passing undefined here
              // would override the hardcode via the spread).
              label: `${original.label} + Engine`,
              totalYards: original.totalYards + res.option.totalYards,
              // Renderer (WorkoutBlock) checks for subBlocks first and
              // renders each as its own labeled box if present. Engine
              // sub-block carries __engineMeta for the ⚡ badge.
              subBlocks: [
                {
                  label: original.label,
                  totalYards: original.totalYards,
                  sets: original.sets,
                },
                {
                  label: res.option.label,
                  totalYards: res.option.totalYards,
                  sets: res.option.sets,
                  __engineMeta: { template_id: res.templateUsed, stroke },
                },
              ],
              // Pass-through `sets` (concatenated) for backward compat
              // with code that reads block.sets directly (totals, print).
              sets: [...original.sets, ...res.option.sets],
              // Top-level engineMeta marks "this section used the engine"
              // for the write-side path that prepends to recent[].
              __engineMeta: { template_id: res.templateUsed, stroke },
            };
          }
          // else: no applicable engine template → silent bank fallback
        }
      }
      return out;
    }

export function generateWorkout({
      typeId,
      maxYards,
      equipment,
      favorites = [],
      poolMode = "25y",
      userMin = null,
      pinnedBlocks = {},
      recentLabels = [],
      recoveryMode = false,
      phase = null,
      favoriteSetIds = null,
      sectionBias = "balanced",
      sectionSources = null,            // S3 — { warmup, drill, main, cooldown } ∈ { bank, engine, mix }
      recentEngineTemplates = [],       // S3 — anti-repeat memory (last 10 { template_id, stroke, ts })
      disfavorites = [],                // v1.2 — labels with 0.25× pick weight (mutex with favorites)
      engineDisfavorites = [],          // v1.3 — (template_id, stroke) tuples with 0.25× engine pick weight
      engineFavorites = [],             // v1.13 — (template_id, stroke) tuples with 3× engine pick weight
      disfavorSetIds = null,            // v1.5 — Set<set_id> with 0.25× weight per match (mutex with favoriteSetIds)
      disfavorMode = "downweight",      // v1.8 — "downweight" (0.25×) or "exclude" (hard-exclude, weight 0)
      lanesPaceSecs = null,             // v2.0 — array of lane paces (sec/100). When set, picker filters options that don't fit all lanes (see optionFitsAllLanes). null/empty = single-pace path unchanged.
      ugcOverlay = null,                // UGC Phase B — caller's UGC overlay (12-key shape); merged into bank picker per exact pool mode.
      myConstraints = [],               // Phase 3 PSC slice 2 — caller's active swimmer_constraints rows. Step-0 hard-exclude. Skipped entirely in multi-lane mode (per scope §3.5; per-lane sub lands in slice 3).
      tonightOverrides = [],             // Phase 3 PSC slice 3 — in-memory constraint rows added at Generate time from the per-practice checklist. Unioned with myConstraints; never persisted.
      includedSections = ["warmup", "drill", "main", "cooldown"],   // Section model A1 — which sections to build. Default = all 4 (byte-identical to pre-A1). `main` is always required. Subsetting wired in A2.
    } = {}) {
      // Lesson tier (Phase 5) — force the fixed 3-section shape (Warm-Up / Skill
      // Focus / Send-off). drill + kick are excluded; the main slot carries Skill
      // Focus (drill-bank-sourced via getBankOptions). Done here so the shape holds
      // regardless of what the caller passes for includedSections.
      const isLesson = typeId === "lesson";
      if (isLesson) includedSections = LESSON_SECTIONS;
      // Section model A1 — per-section inclusion flags. With the default all-4
      // list every flag is true, so all downstream guards are inert.
      const _incl = {
        warmup:   includedSections.includes("warmup"),
        drill:    includedSections.includes("drill"),
        kick:     includedSections.includes("kick"),        // kick — opt-in 5th section (defaults excluded)
        main:     true,                                     // main is never skippable
        cooldown: includedSections.includes("cooldown"),
      };
      // Section model A3 — excluded sections behave as pinned EMPTY blocks: the
      // solver's pinned path uses them as-is (0 yards, never picked from the
      // pool), applyEngineOverrides leaves 0-yard blocks untouched, and they
      // contribute 0 to pinnedTotal — so freeBudget is unchanged and flows to
      // the remaining sections (main absorbs the slack), holding the target.
      // buildWorkout then filters the empty blocks out of the output.
      const _EMPTY_SECTION = { label: "", totalYards: 0, sets: [] };
      pinnedBlocks = {
        ...pinnedBlocks,
        ...(_incl.warmup   ? {} : { warmup:   _EMPTY_SECTION }),
        ...(_incl.drill    ? {} : { drill:    _EMPTY_SECTION }),
        ...(_incl.kick     ? {} : { kick:     _EMPTY_SECTION }),
        ...(_incl.cooldown ? {} : { cooldown: _EMPTY_SECTION }),
      };
      // v1.8 — Resolve the multiplier once. "exclude" zeros the weight;
      // pickWeighted's existing "all weights zero → uniform fallback" is the
      // silent failsafe when hard-exclude would empty the eligible pool.
      const disfavorMultiplier = disfavorMode === "exclude" ? 0 : 0.25;
      // Lesson tier (Phase 5) — make the Skill Focus the bulk of the session
      // (warmup/send-off small) by defaulting to the main-heavy bias. The drill
      // exclusion above renormalizes the ratio over {warmup, main, cooldown}, so
      // the freed drill share flows to Skill Focus. A caller-set bias still wins.
      const _effBias = (isLesson && sectionBias === "balanced") ? "long_main" : sectionBias;
      let biasRatios = SECTION_BIAS_RATIOS[_effBias] || null;
      // Section model A3 — when a section is skipped, renormalize the Mix bias
      // shares over the INCLUDED sections so the freed share redistributes
      // proportionally (without this, a skipped section's reserved % is lost).
      // Guarded to the skipped case: the all-4 path keeps the literal ratios
      // (no float drift), preserving byte-identical output.
      if (biasRatios && (!_incl.warmup || !_incl.drill || !_incl.cooldown)) {
        const _sum = ["warmup", "drill", "main", "cooldown"]
          .reduce((s, k) => s + (_incl[k] ? (biasRatios[k] || 0) : 0), 0);
        if (_sum > 0) {
          biasRatios = {
            warmup:   _incl.warmup   ? biasRatios.warmup   / _sum : 0,
            drill:    _incl.drill    ? biasRatios.drill    / _sum : 0,
            main:                      biasRatios.main      / _sum,
            cooldown: _incl.cooldown ? biasRatios.cooldown / _sum : 0,
          };
        }
      }
      const is25m    = poolMode === "25m";
      const is50m    = poolMode === "50m";
      const isMeters = is25m || is50m;
      // Unit-aware bank lookup. Each call returns options already in the
      // user's pool unit (converted from yd↔m if the fallback crossed banks).
      // UGC overlay (Phase B+) is appended in getBankOptions per exact pool mode.
      const _allWarmupsRaw   = getBankOptions("warmup",   typeId, poolMode, ugcOverlay);
      const _allCooldownsRaw = getBankOptions("cooldown", typeId, poolMode, ugcOverlay);
      const _drillListRaw    = getBankOptions("drill",    typeId, poolMode, ugcOverlay);
      const _kickListRaw     = getBankOptions("kick",     typeId, poolMode, ugcOverlay);
      const _mainListRaw     = getBankOptions("main",     typeId, poolMode, ugcOverlay);

      // Phase 3 PSC slice 2/3 — hard-exclude step 0. Per
      // PER_SWIMMER_CONSTRAINTS_SCOPE.md §3.4: drop options before weight
      // computation. SKIPPED entirely in multi-lane mode (fork 1 with Cap'n
      // 2026-05-26: per-lane substitution rendering lands in slice 3+).
      // Bank fallback: if PSC empties a pool, use the unfiltered pool so
      // generation never stalls (silent per fork 3; substitution rendering
      // is slice 3+). Tracked in `pscFilterFallback` for debug only.
      // Slice 3: tonightOverrides (per-practice checklist) unions with
      // persistent myConstraints — both feed the same picker filter.
      const _effectiveConstraints = [...(myConstraints || []), ...(tonightOverrides || [])];
      const usePsc = _effectiveConstraints.length > 0 && !(Array.isArray(lanesPaceSecs) && lanesPaceSecs.length > 0);
      const pscFilterFallback = { warmup: false, drill: false, kick: false, main: false, cooldown: false };
      const _narrowByPsc = (pool, sectionKey) => {
        if (!usePsc) return pool;
        const filtered = pool.filter(o => !optionViolatesPSC(o, _effectiveConstraints));
        if (filtered.length === 0) {
          pscFilterFallback[sectionKey] = true;
          return pool;
        }
        return filtered;
      };
      const _allWarmupsPsc   = _narrowByPsc(_allWarmupsRaw,   "warmup");
      const _allCooldownsPsc = _narrowByPsc(_allCooldownsRaw, "cooldown");
      const _drillListPsc    = _narrowByPsc(_drillListRaw,    "drill");
      const _kickListPsc     = _narrowByPsc(_kickListRaw,     "kick");
      const _mainListPsc     = _narrowByPsc(_mainListRaw,     "main");

      // v2.0 — Multi-lane lane-fit pre-filter. When lanesPaceSecs is non-empty,
      // narrow each pool to options whose intervals fit ALL lanes (rest ∈
      // [MIN_REST, MAX_REST_RATIO × swimTime]). Graceful fallback per section:
      // if the filter empties a pool, fall back to the unfiltered pool and
      // flag laneFitFallback so the UI can surface a "lanes too wide" warning.
      // When lanesPaceSecs is null/empty, the filter is a no-op and the path
      // is byte-identical to the single-pace flow.
      const useLaneFit = Array.isArray(lanesPaceSecs) && lanesPaceSecs.length > 0;
      const laneFitFallback = { warmup: false, drill: false, kick: false, main: false, cooldown: false };
      const _narrowByLanes = (pool, sectionKey) => {
        if (!useLaneFit) return pool;
        const filtered = pool.filter(o => optionFitsAllLanes(o, lanesPaceSecs));
        if (filtered.length === 0) {
          laneFitFallback[sectionKey] = true;
          return pool;
        }
        return filtered;
      };
      const allWarmups   = _narrowByLanes(_allWarmupsPsc,   "warmup");
      const allCooldowns = _narrowByLanes(_allCooldownsPsc, "cooldown");
      const drillList    = _narrowByLanes(_drillListPsc,    "drill");
      const kickList     = _narrowByLanes(_kickListPsc,     "kick");
      let   mainList     = _narrowByLanes(_mainListPsc,     "main");

      // C: recovery mode — filter mains down to easy/aerobic zone options.
      // If the filter would empty the pool, fall back to all mains and let
      // the +10% interval stretch + repeat-suppression carry the recovery
      // intent on its own.
      if (recoveryMode) {
        const recoveryMains = mainList.filter(o => {
          const z = inferBlockZone({ section: "main", sets: o.sets, primary_zone: o.primary_zone });
          return z === "easy" || z === "aerobic";
        });
        if (recoveryMains.length) mainList = recoveryMains;
      }

      // Fixed yardage from pinned sections; free budget is what remains for unpinned picks
      const pinnedTotal = (pinnedBlocks.warmup   ? pinnedBlocks.warmup.totalYards   : 0)
                        + (pinnedBlocks.drill    ? pinnedBlocks.drill.totalYards    : 0)
                        + (pinnedBlocks.kick     ? pinnedBlocks.kick.totalYards     : 0)
                        + (pinnedBlocks.main     ? pinnedBlocks.main.totalYards     : 0)
                        + (pinnedBlocks.cooldown ? pinnedBlocks.cooldown.totalYards : 0);
      const freeBudget  = maxYards - pinnedTotal;
      const hasPins     = pinnedTotal > 0;

      // Per-section minimums (0 for pinned sections — they don't consume free budget)
      const minWu = (pinnedBlocks.warmup   || !_incl.warmup)   ? 0 : Math.min(...allWarmups.map(o => o.totalYards));
      const minDr = (pinnedBlocks.drill    || !_incl.drill)    ? 0 : Math.min(...drillList.map(o => o.totalYards));
      const minKt = (pinnedBlocks.kick || !_incl.kick || !kickList.length) ? 0 : Math.min(...kickList.map(o => o.totalYards));
      const minMa = pinnedBlocks.main     ? 0 : Math.min(...mainList.map(o => o.totalYards));
      const minCd = (pinnedBlocks.cooldown || !_incl.cooldown) ? 0 : Math.min(...allCooldowns.map(o => o.totalYards));

      // C: recovery mode drops the absolute floor to 1200y (1300m) so a short
      // easy day is allowed regardless of the type's normal minimum.
      const recoveryFloor = isMeters ? 1300 : 1200;
      const baseAbsMin = isLesson
        ? LESSON_MIN                                   // Lesson tier — short sessions allowed (200yd/m floor).
        : recoveryMode
          ? Math.min(recoveryFloor, isMeters ? MIN_METERS : MIN_YARDS)
          : (isMeters ? MIN_METERS : MIN_YARDS);
      const absoluteMin = Math.max(baseAbsMin, userMin || 0);
      // S3 #4 — Floor scales with target so unpinned workouts stay close to maxYards.
      // Relaxed when (a) pins are present (user chose those blocks intentionally),
      // or (b) recovery mode is on — recovery wants a SHORT easy day, so the
      // -400 "stay near max" rule is dropped to let the absoluteMin (= 1200y /
      // 1300m floor from baseAbsMin) actually bite.
      const minTotal = (hasPins || recoveryMode)
        ? absoluteMin
        : Math.max(absoluteMin, maxYards - 400);

      const hasEquipReq = equipment && Object.keys(EQUIP_REQUIREMENTS).some(k => isEquipRequired(equipment, k));

      const attempts = (maxYards >= 3000 || hasEquipReq) ? 80 : 30;

      // Favorite-label boost shared by all section pickers. Returns 3 when
      // option's label is in the user's favorites (matching the existing
      // mainWeight × 3 bias), 1 otherwise. Cross-mode parallels share labels,
      // so favoriting "IM Warmup" in SCY also boosts the SCM/LCM versions.
      const favSet = new Set(favorites || []);
      // v1.2 — disfavor: 0.25× weight, mutually exclusive with favorite
      // (enforced at the DB layer; defensive check here in case a label is
      // somehow in both sets — favorite wins).
      const disfavorSet = new Set(disfavorites || []);
      const favBoost = (o) => {
        if (!o.label) return 1;
        if (favSet.has(o.label))      return 3;                  // favorite × 3
        if (disfavorSet.has(o.label)) return disfavorMultiplier; // v1.8: downweight (0.25) or exclude (0)
        return 1;
      };

      function pickBiased(arr, floor) {
        const preferred = arr.filter(o => o.totalYards >= floor);
        const source = preferred.length > 0 ? preferred : arr;
        // Apply favorite × 3 bias even on the floor-filtered pool.
        return pickWeighted(source, favBoost);
      }

      // Section-proportion helper. Picks from arr with weights that combine
      // a base weight function (e.g. favBoost, equipment-match) and an
      // inverse-quadratic distance penalty from a target yardage. Used by
      // warmup + drill pickers when sectionBias != "balanced".
      //   weight(opt) = base(opt) / (1 + |opt.totalYards - target| / target)^2
      // distance=0 → 1.0× base; distance=target → 0.25× base; distance=2×target → ~0.11× base.
      function pickWithTargetYards(arr, target, baseFn) {
        return pickWeighted(arr, (o) => {
          const distRatio = Math.abs((o.totalYards || 0) - target) / Math.max(1, target);
          const penalty = 1 / Math.pow(1 + distRatio, 2);
          return (baseFn ? baseFn(o) : 1) * penalty;
        });
      }

      for (let attempt = 0; attempt < attempts; attempt++) {
        let freeUsed = 0; // yards committed to unpinned sections this attempt

        // 1. Warmup
        let wu;
        if (pinnedBlocks.warmup) {
          wu = pinnedBlocks.warmup;
        } else {
          const validWarmups = allWarmups.filter(o =>
            o.totalYards <= freeBudget - minDr - minKt - minMa - minCd
          );
          if (!validWarmups.length) break;
          // Prefer warmups whose typeAffinity matches the workout type family
          const warmupFamily = TYPE_WARMUP_FAMILY[typeId] || null;
          const affinityPool = warmupFamily
            ? validWarmups.filter(o => o.typeAffinity && o.typeAffinity.includes(warmupFamily))
            : validWarmups;
          // S4 #12 — Use total maxYards (not freeBudget) for the floor. With
          // pinned drill+main+cooldown, freeBudget shrinks to just the warmup's
          // remaining share, so a 12%-of-freeBudget floor becomes essentially
          // zero. Tying to maxYards keeps the floor proportional to the
          // intended workout size regardless of pin state.
          const wuPool = affinityPool.length > 0 ? affinityPool : validWarmups;
          if (biasRatios) {
            // Real-shift: target yardage from bias ratios, distance-weighted.
            wu = pickWithTargetYards(wuPool, freeBudget * biasRatios.warmup, favBoost);
          } else {
            wu = pickBiased(wuPool, maxYards * 0.12);
          }
          freeUsed += wu.totalYards;
        }

        // 2. Drill — F: bias picks toward drills that satisfy a "preferred"
        // equipment item (one match = ×2 weight per match). Required-equipment
        // hard filter still happens in combinationSatisfies after main picks.
        let dr;
        if (pinnedBlocks.drill) {
          dr = pinnedBlocks.drill;
        } else {
          const validDrills = drillList.filter(o =>
            o.totalYards <= freeBudget - freeUsed - minKt - minMa - minCd
          );
          if (!validDrills.length) continue;
          const drillBase = (o) => Math.pow(2, preferredEquipMatches(o, equipment)) * favBoost(o);
          if (biasRatios) {
            // Real-shift: target by bias; no 10% floor (target weighting handles spread).
            dr = pickWithTargetYards(validDrills, freeBudget * biasRatios.drill, drillBase);
          } else {
            const drFloor = (freeBudget - freeUsed) * 0.10;
            const aboveFloor = validDrills.filter(o => o.totalYards >= drFloor);
            const drPool = aboveFloor.length > 0 ? aboveFloor : validDrills;
            dr = pickWeighted(drPool, drillBase);
          }
          freeUsed += dr.totalYards;
        }

        // 2b. Kick (optional 5th section — defaults excluded). Drawn from free
        // budget after drill; no bias target (kick isn't in SECTION_BIAS_RATIOS).
        let kt;
        if (pinnedBlocks.kick) {
          kt = pinnedBlocks.kick;
        } else {
          const validKicks = kickList.filter(o =>
            o.totalYards <= freeBudget - freeUsed - minMa - minCd
          );
          if (!validKicks.length) continue;
          const kickBase = (o) => Math.pow(2, preferredEquipMatches(o, equipment)) * favBoost(o);
          kt = pickWeighted(validKicks, kickBase);
          freeUsed += kt.totalYards;
        }

        // 3. Main — expand pool with ×2 and ×3 repeat variants
        //    (C: recovery mode skips the repeat expansion — short and sweet)
        let ma;
        if (pinnedBlocks.main) {
          ma = pinnedBlocks.main;
        } else {
          const mainBudget = freeBudget - freeUsed - minCd;
          const mainPoolExpanded = recoveryMode
            ? mainList.slice()
            : mainList.flatMap(o => {
                const variants = [o];
                for (const r of [2, 3]) {
                  const rep = { ...o, rounds: r, totalYards: o.totalYards * r };
                  if (rep.totalYards <= mainBudget) variants.push(rep);
                }
                return variants;
              });
          const validMain = mainPoolExpanded.filter(o => o.totalYards <= mainBudget);
          if (!validMain.length) continue;
          // S3 #4 — main set normally takes ≥65% of the remaining budget so
          // workouts feel substantive. In recovery mode we want a SHORT day,
          // so the 65% rule is dropped: any main that fits the budget is fair
          // game, down to the absolute minimum (minMa).
          // Real-shift bias: override the 65% floor with the bias-specific
          // main ratio applied to freeBudget (target absolute, not relative
          // to whatever's left after warmup+drill grabbed). long_main pushes
          // floor to ~83%; drill/warmup-heavy modes lower it so the other
          // sections can absorb more.
          let mainFloorRatio;
          if (recoveryMode)       mainFloorRatio = null;
          else if (biasRatios)    mainFloorRatio = biasRatios.main;
          else                    mainFloorRatio = 0.65;
          const maFloor = (mainFloorRatio == null)
            ? minMa
            : Math.max(minMa, Math.min(mainBudget, freeBudget * mainFloorRatio));
          // Weighting:
          //   base    = 1
          //   favorite× 3
          //   repeat(rounds > 1) × 2
          //   recently-used label (last 7d) × 0.25  ← N1 anti-repeat
          //   phase-zone multiplier (e.g. taper: easy×1.5, vo2×0.5) ← N5
          //   preferred-equipment match × 2 per item ← F
          //
          // S4 #9 — Label-keyed lookups (favorites, recentSet) are working as
          // "anti-repeat by family": when the same conceptual workout (e.g.
          // "IM Descend") is authored across pool modes (SCY/SCM/LCM) or types
          // (im / mixed), they share a label, so down-weighting one down-weights
          // all variants. That's the intended behavior. Labels that *aren't*
          // meant to share semantics MUST stay globally unique.
          // 2026-05-15: catalog favorites now expose warmup/drill/cooldown
          // labels to the favorites array too. Verified zero cross-section
          // collisions (618 unique labels). New bank entries must keep this
          // invariant — re-run tools/check_label_collisions.py if added.
          const recentSet = new Set(recentLabels);
          const phaseSpec = phase && PHASES[phase] ? PHASES[phase] : null;
          const mainWeight = (o) => {
            let w = 1;
            // v1.13 — UNIVERSAL precedence rule: presence in ANY favorite list
            // (own or coach-propagated, since `favorites` is the unioned set
            // by the time it reaches here) skips the disfavor multiplier
            // entirely. Same per-set: if a set is favorited, it does NOT
            // also get the disfavor multiplier even if its ID is in the
            // disfavor set. Previously (≤ v1.12) these multiplied, so a
            // favorite+disfavor collision yielded 0.75×; now favorite wins.
            const isLabelFav = !!(favorites.length && o.label && favorites.includes(o.label));
            if (isLabelFav) {
              w *= 3;
            } else if (disfavorites.length && o.label && disfavorites.includes(o.label)) {
              w *= disfavorMultiplier;
            }
            // Per-set: count fav vs disfavor matches PER SET and apply 3× per
            // favorited set OR disfavorMultiplier per disfavored set — never
            // both for the same set (favorite wins on collisions). Mutex at
            // DB layer already prevents own collisions; coach-propagated
            // values can still collide with own, hence the per-set check.
            if (Array.isArray(o.sets) && ((favoriteSetIds && favoriteSetIds.size) || (disfavorSetIds && disfavorSetIds.size))) {
              let favSetMatches = 0;
              let disSetMatches = 0;
              for (const s of o.sets) {
                if (!s.id) continue;
                if (favoriteSetIds && favoriteSetIds.has(s.id))      favSetMatches++;
                else if (disfavorSetIds && disfavorSetIds.has(s.id)) disSetMatches++;
              }
              if (favSetMatches > 0) w *= Math.pow(3, favSetMatches);
              if (disSetMatches > 0) w *= Math.pow(disfavorMultiplier, disSetMatches);
            }
            if ((o.rounds || 1) > 1) w *= 2;
            if (o.label && recentSet.has(o.label)) w *= 0.25;
            if (phaseSpec) {
              const optionZone = inferBlockZone({ section: "main", sets: o.sets, primary_zone: o.primary_zone });
              const m = phaseSpec.multipliers[optionZone];
              if (typeof m === "number") w *= m;
            }
            const prefMatches = preferredEquipMatches(o, equipment);
            if (prefMatches > 0) w *= Math.pow(2, prefMatches);
            return w;
          };
          const filteredByFloor = validMain.filter(o => o.totalYards >= maFloor);
          const mainSource = filteredByFloor.length > 0 ? filteredByFloor : validMain;
          ma = pickWeighted(mainSource, mainWeight);
          freeUsed += ma.totalYards;
        }

        // 4. Equipment satisfaction check
        if (hasEquipReq && !combinationSatisfies(dr, ma, equipment)) continue;

        // 5. Cooldown
        let cd;
        if (pinnedBlocks.cooldown) {
          cd = pinnedBlocks.cooldown;
        } else {
          const remaining = freeBudget - freeUsed;
          const validCooldowns = allCooldowns.filter(o => o.totalYards <= remaining);
          if (!validCooldowns.length) continue;
          cd = pickWeighted(validCooldowns, favBoost);
        }

        const total = wu.totalYards + dr.totalYards + kt.totalYards + ma.totalYards + cd.totalYards;
        if (total >= minTotal && total <= maxYards) {
          // S3 — apply engine overrides per section, then recompute total
          const overridden = applyEngineOverrides(typeId, { warmup: wu, drill: dr, kick: kt, main: ma, cooldown: cd }, sectionSources, recentEngineTemplates, engineDisfavorites, disfavorMode, engineFavorites, lanesPaceSecs, usePsc ? _effectiveConstraints : []);
          const finalTotal = overridden.warmup.totalYards + overridden.drill.totalYards + overridden.kick.totalYards + overridden.main.totalYards + overridden.cooldown.totalYards;
          // S3 #19 — telemetry: how often does the random-attempt loop succeed?
          // v2.0 — attach laneFit fallback marker (closure vars live in generateWorkout scope).
          const _laneFitFallbackSections = useLaneFit
            ? Object.entries(laneFitFallback).filter(([_, v]) => v).map(([k]) => k)
            : [];
          const _loopResult = { ...buildWorkout(typeId, overridden.warmup, overridden.drill, overridden.kick, overridden.main, overridden.cooldown, finalTotal, includedSections), __genPath: "loop", __genAttempts: attempt + 1 };
          if (_laneFitFallbackSections.length) _loopResult.__laneFitFallback = _laneFitFallbackSections;
          return _loopResult;
        }
      }

      // Fallback: largest valid combination, respecting pins
      const byYardsDesc = (a, b) => b.totalYards - a.totalYards;
      let fbFree = 0;

      let wu;
      if (pinnedBlocks.warmup) {
        wu = pinnedBlocks.warmup;
      } else {
        const wuPool = allWarmups.filter(o => o.totalYards <= freeBudget - minDr - minMa - minCd);
        wu = (wuPool.length ? wuPool.slice().sort(byYardsDesc) : allWarmups.slice().sort(byYardsDesc))[0];
        fbFree += wu.totalYards;
      }

      let dr;
      if (pinnedBlocks.drill) {
        dr = pinnedBlocks.drill;
      } else {
        let drCandidates = drillList.filter(o => o.totalYards <= freeBudget - fbFree - minMa - minCd);
        if (!drCandidates.length) drCandidates = drillList;
        drCandidates = drCandidates.slice().sort(byYardsDesc);
        if (hasEquipReq) {
          const eqPreferred = drCandidates.filter(d =>
            mainList.some(m =>
              m.totalYards <= freeBudget - fbFree - d.totalYards - minKt - minCd &&
              combinationSatisfies(d, m, equipment)
            )
          );
          // S3 #3 — if NO drill+main combination satisfies the required-equipment
          // set, return a failure sentinel instead of silently dropping the filter.
          // The user asked for that equipment to be required; honor it.
          if (!eqPreferred.length) {
            return { __generateFailure: true, reason: "equipment_unsatisfiable",
                     error: "No drill + main combination covers all your required equipment at this max-yardage. Try lowering an item to 'preferred', or raising the max-yardage." };
          }
          drCandidates = eqPreferred;
        }
        dr = drCandidates[0];
        fbFree += dr.totalYards;
      }

      // Kick (optional 5th section). Excluded → pinnedBlocks.kick is the empty
      // section (0 yards). Included with options → largest that fits. If
      // included but no kick options exist, fall back to an empty section.
      let kt;
      if (pinnedBlocks.kick) {
        kt = pinnedBlocks.kick;
      } else if (_incl.kick && kickList.length) {
        let ktCandidates = kickList.filter(o => o.totalYards <= freeBudget - fbFree - minMa - minCd);
        if (!ktCandidates.length) ktCandidates = kickList;
        kt = ktCandidates.slice().sort(byYardsDesc)[0];
        fbFree += kt.totalYards;
      } else {
        kt = { label: "", totalYards: 0, sets: [] };
      }

      let ma;
      if (pinnedBlocks.main) {
        ma = pinnedBlocks.main;
      } else {
        const fbMainBudget = freeBudget - fbFree - minCd;
        const fbMainExpanded = recoveryMode
          ? mainList.slice()
          : mainList.flatMap(o => {
              const variants = [o];
              for (const r of [2, 3]) {
                const rep = { ...o, rounds: r, totalYards: o.totalYards * r };
                if (rep.totalYards <= fbMainBudget) variants.push(rep);
              }
              return variants;
            });
        let mainCandidates = fbMainExpanded.filter(o => o.totalYards <= fbMainBudget);
        if (!mainCandidates.length) mainCandidates = mainList;
        mainCandidates = mainCandidates.slice().sort(byYardsDesc);
        if (hasEquipReq) {
          const eqMain = mainCandidates.filter(m => combinationSatisfies(dr, m, equipment));
          // S3 #3 — defensive: the eqPreferred check above guarantees a matching
          // main exists for the chosen drill, so this should never be empty. If
          // it is, the invariant has been violated — fail rather than mis-satisfy.
          if (!eqMain.length) {
            return { __generateFailure: true, reason: "equipment_unsatisfiable_for_drill",
                     error: "Selected drill has no compatible main set for your required equipment. Try regenerating or adjusting equipment." };
          }
          mainCandidates = eqMain;
        }
        ma = mainCandidates[0];
        fbFree += ma.totalYards;
      }

      let cd;
      if (pinnedBlocks.cooldown) {
        cd = pinnedBlocks.cooldown;
      } else {
        const cdPool = allCooldowns.filter(o => o.totalYards <= freeBudget - fbFree);
        cd = (cdPool.length ? cdPool.slice().sort(byYardsDesc) : allCooldowns.slice().sort(byYardsDesc))[0];
      }

      const total = wu.totalYards + dr.totalYards + kt.totalYards + ma.totalYards + cd.totalYards;
      // S3 — apply engine overrides per section, then recompute total
      const overridden = applyEngineOverrides(typeId, { warmup: wu, drill: dr, kick: kt, main: ma, cooldown: cd }, sectionSources, recentEngineTemplates, engineDisfavorites, disfavorMode, engineFavorites, lanesPaceSecs, usePsc ? _effectiveConstraints : []);
      const finalTotal = overridden.warmup.totalYards + overridden.drill.totalYards + overridden.kick.totalYards + overridden.main.totalYards + overridden.cooldown.totalYards;
      // S3 #19 — telemetry: fallback path fired (random loop exhausted attempts).
      // v2.0 — same laneFit attachment as the loop-success path above.
      const _fallbackLaneFitSections = useLaneFit
        ? Object.entries(laneFitFallback).filter(([_, v]) => v).map(([k]) => k)
        : [];
      const _fallbackResult = { ...buildWorkout(typeId, overridden.warmup, overridden.drill, overridden.kick, overridden.main, overridden.cooldown, finalTotal, includedSections), __genPath: "fallback", __genAttempts: attempts };
      if (_fallbackLaneFitSections.length) _fallbackResult.__laneFitFallback = _fallbackLaneFitSections;
      return _fallbackResult;
    }

export function buildWorkout(typeId, wu, dr, kt, ma, cd, total, includedSections = ["warmup", "drill", "main", "cooldown"]) {
      // Lesson tier (Phase 5) — relabel the 3 surfaced blocks: Warm-Up / Skill
      // Focus / Send-off. "Skill Focus" rides the main slot (drill-bank-sourced),
      // so it stays section:"main" internally (regenerate/pace/analytics all keyed
      // on section) but never reads "Main Set" in the UI.
      const isLesson = typeId === "lesson";
      const mainLabelPrefix = isLesson ? "Skill Focus" : "Main Set";
      const mainName = ma.rounds > 1
        ? `${mainLabelPrefix} — ${ma.label} ×${ma.rounds}`
        : `${mainLabelPrefix} — ${ma.label}`;
      // Section model A1 — assemble the candidate blocks, then keep only
      // included sections (default = warmup/drill/main/cooldown → byte-identical
      // to pre-A1; kick is opt-in and dropped here unless includedSections names it).
      const blocks = [
        { name: "Warm-Up",              section: "warmup",   ...wu },
        { name: "Drill / Pre-Main Set", section: "drill",    ...dr },
        { name: "Kick Set",             section: "kick",     ...kt },
        { name: mainName, section: "main", ...ma, roundRestSecs: ma.roundRestSecs ?? 30 },
        { name: isLesson ? "Send-off" : "Cool-Down", section: "cooldown", ...cd },
      ].filter(b => includedSections.includes(b.section));
      const estimatedMin = calcEstimatedMin(blocks);
      // Section model A2 — total reflects only the INCLUDED blocks: honest when
      // a section is skipped, and identical to the passed `total` when all four
      // are present (sum of the four blocks === finalTotal).
      const includedTotal = blocks.reduce((s, b) => s + (b.totalYards || 0), 0);
      return { blocks, totalYards: includedTotal, estimatedMin, typeId };
      // NOTE: __laneFitFallback attachment happens at the buildWorkout
      // call sites inside generateWorkout — buildWorkout is module-scope
      // and can't see generateWorkout's locals (useLaneFit, laneFitFallback).
    }

export const SECTION_KEYS = ["warmup", "drill", "kick", "main", "cooldown"];

export function sectionFingerprint(b) {
      if (!b || !Array.isArray(b.sets)) return "";
      const sig = b.sets.map(s => `${s.reps}x${s.dist}|${s.desc}`).join("/");
      return `${b.totalYards}|r${b.rounds || 1}|${sig}`;
    }

export function regenerateSection({
      workout,
      typeId,
      sectionKey,
      maxYards,
      equipment,
      poolMode = "25y",
      userMin = null,
      recentLabels = [],
      recoveryMode = false,
      phase = null,
      favorites = [],
      favoriteSetIds = null,         // Gap-1 (2026-05-22) — Set<set_id> with 3× weight per match on main section
      engineFavorites = [],          // v1.13 — (template_id, stroke) tuples with 3× engine pick weight
      sectionSource = "bank",        // S3 — bank | engine | mix
      recentEngineTemplates = [],    // S3 — anti-repeat memory
      disfavorites = [],             // v1.2 — labels with 0.25× pick weight
      engineDisfavorites = [],       // v1.3 — (template_id, stroke) tuples with 0.25× engine pick weight
      disfavorSetIds = null,         // Gap-1 (2026-05-22) — Set<set_id> with 0.25× weight per match on main section
      disfavorMode = "downweight",   // v1.8 — "downweight" (0.25) or "exclude" (0)
      lanesPaceSecs = null,          // v2.0 — multi-lane fit filter on the section's pool
      ugcOverlay = null,             // UGC Phase B — caller's UGC overlay merged into bank picker per exact pool mode
      myConstraints = [],            // Phase 3 PSC slice 2 — caller's active swimmer_constraints rows. Step-0 hard-exclude. Skipped in multi-lane mode.
      tonightOverrides = [],          // Phase 3 PSC slice 3 — in-memory per-practice overrides; unioned with myConstraints.
    } = {}) {
      // v1.8 — Resolve once for use below.
      const disfavorMultiplier = disfavorMode === "exclude" ? 0 : 0.25;
      // Phase 3 PSC slice 2/3 — same skip-in-multi-lane rule as generateWorkout.
      const _useLaneFitRegen     = Array.isArray(lanesPaceSecs) && lanesPaceSecs.length > 0;
      const _effectiveCRegen     = [...(myConstraints || []), ...(tonightOverrides || [])];
      const _usePscRegen         = _effectiveCRegen.length > 0 && !_useLaneFitRegen;
      // Section lookup below is by section key (findIndex), not by position or
      // count, so we only require a non-empty blocks array here. A fixed 4/5
      // bound would wrongly reject workouts with skipped sections (fewer swim
      // blocks) or added dryland blocks (which also live in `blocks`).
      if (!workout || !Array.isArray(workout.blocks) || workout.blocks.length === 0) {
        return { workout: null, error: "No workout to update." };
      }
      if (!SECTION_KEYS.includes(sectionKey)) return { workout: null, error: "Unknown section." };

      const is25m    = poolMode === "25m";
      const is50m    = poolMode === "50m";
      const isMeters = is25m || is50m;
      const blocks = workout.blocks;
      // Match the target block by section, not positional index — kick can be
      // inserted between drill and main, shifting positions.
      const idx = blocks.findIndex(b => b.section === sectionKey);
      if (idx < 0) return { workout: null, error: "Unknown section." };
      const current = blocks[idx];
      const others = blocks.reduce((sum, b, i) => i === idx ? sum : sum + b.totalYards, 0);
      // Lesson tier (Phase 5) — short-session floor (200yd/m) instead of MIN_YARDS.
      const _floorMin = typeId === "lesson" ? LESSON_MIN : (isMeters ? MIN_METERS : MIN_YARDS);
      const lower = Math.max(0, Math.max(_floorMin, userMin || 0) - others);
      const upper = maxYards - others;

      let pool;
      if (sectionKey === "warmup")        pool = getBankOptions("warmup",   typeId, poolMode, ugcOverlay);
      else if (sectionKey === "cooldown") pool = getBankOptions("cooldown", typeId, poolMode, ugcOverlay);
      else if (sectionKey === "drill")    pool = getBankOptions("drill",    typeId, poolMode, ugcOverlay);
      else if (sectionKey === "kick")     pool = getBankOptions("kick",     typeId, poolMode, ugcOverlay);
      else {
        let basePool = getBankOptions("main", typeId, poolMode, ugcOverlay);
        // C: in recovery mode, only consider easy/aerobic mains, no repeat variants.
        if (recoveryMode) {
          const recoveryMains = basePool.filter(o => {
            const z = inferBlockZone({ section: "main", sets: o.sets, primary_zone: o.primary_zone });
            return z === "easy" || z === "aerobic";
          });
          if (recoveryMains.length) basePool = recoveryMains;
          pool = basePool.slice();
        } else {
          // Expand with ×2 and ×3 repeat variants
          pool = basePool.flatMap(o => {
            const variants = [o];
            for (const r of [2, 3]) {
              variants.push({ ...o, rounds: r, totalYards: o.totalYards * r });
            }
            return variants;
          });
        }
      }
      // Phase 3 PSC slice 2 — hard-exclude step 0, before the lane-fit
      // pre-filter. Skipped in multi-lane mode (per fork 1). Bank-fallback
      // on empty filtered pool — silent (per fork 3).
      if (_usePscRegen) {
        const pscFiltered = pool.filter(o => !optionViolatesPSC(o, _effectiveCRegen));
        if (pscFiltered.length > 0) pool = pscFiltered;
        // else: silent bank fallback (caller has no actionable recovery)
      }
      // v2.0 — Multi-lane fit pre-filter on the section's pool. Same
      // graceful fallback as generateWorkout (use unfiltered if empty).
      let _laneFitFallback = false;
      if (_useLaneFitRegen) {
        const filtered = pool.filter(o => optionFitsAllLanes(o, lanesPaceSecs));
        if (filtered.length > 0) pool = filtered;
        else                     _laneFitFallback = true;
      }

      const hasEquipReq = equipment && Object.keys(EQUIP_REQUIREMENTS).some(k => isEquipRequired(equipment, k));
      const partnerDrill = blocks.find(b => b.section === "drill") || blocks[1]; // used when regenerating main
      const partnerMain  = blocks.find(b => b.section === "main")  || blocks[2]; // used when regenerating drill

      const passesEquip = (candidate) => {
        if (!hasEquipReq) return true;
        if (sectionKey === "drill") return combinationSatisfies(candidate, partnerMain, equipment);
        if (sectionKey === "main")  return combinationSatisfies(partnerDrill, candidate, equipment);
        return true; // warmup/cooldown carry no equipment tags
      };

      const fitsBudget = (o) => o.totalYards >= lower && o.totalYards <= upper;
      let validAll = pool.filter(o => fitsBudget(o) && passesEquip(o));
      if (!validAll.length) {
        // v1.11 fix — for engine/mix regen, bank validation isn't a hard
        // gate. Engine output replaces the bank pick anyway, and engine
        // generates at the section's target yardage independent of the
        // bank pool. Fall back to bank options that fit equipment but
        // ignore the strict yardage gate (engine will size correctly).
        // If even THAT pool is empty (no equipment-compatible bank option
        // exists at all), engine has nothing to seed from — return error.
        if (sectionSource === "engine" || sectionSource === "mix") {
          validAll = pool.filter(passesEquip);
          if (!validAll.length) {
            return { workout: null, error: hasEquipReq
              ? "No bank option exists for this section to seed the engine and satisfy equipment. Try unrequiring equipment."
              : "No bank option exists for this section to seed the engine." };
          }
        } else {
          return { workout: null, error: hasEquipReq
            ? "No option for this section fits the remaining yardage and your equipment selection."
            : "No option for this section fits the remaining yardage budget." };
        }
      }

      // Prefer type-matched warmups on regen (same logic as generateWorkout)
      if (sectionKey === "warmup") {
        const warmupFamily = TYPE_WARMUP_FAMILY[typeId] || null;
        if (warmupFamily) {
          const affinityPool = validAll.filter(o => o.typeAffinity && o.typeAffinity.includes(warmupFamily));
          if (affinityPool.length > 0) validAll = affinityPool;
        }
      }

      const curFp = sectionFingerprint(current);
      let novel = validAll.filter(o => sectionFingerprint(o) !== curFp);
      if (!novel.length) {
        // v1.11 fix — the novelty check guards bank-mode regen from picking
        // the same bank option again. Engine/Mix regens will produce a
        // freshly-generated engine block downstream regardless of the bank
        // pool size, so requiring bank novelty here mis-blocks them. When
        // engine/mix source is set, fall back to validAll (skip novelty
        // gate). The engine override below replaces the bankBlock.
        if (sectionSource === "engine" || sectionSource === "mix") {
          if (!validAll.length) {
            return { workout: null, error: "No option for this section fits the remaining yardage budget." };
          }
          novel = validAll;  // skip the novelty gate; engine will produce fresh content
        } else {
          return { workout: null, error: "Only one option fits these constraints — adjust max yards or equipment for more variety." };
        }
      }
      // N1: down-weight recently-used labels (main section only — no labels elsewhere).
      // N5: layer phase multipliers on top of the recent-label down-weight.
      // F: boost options whose sets cover any "preferred" equipment (drill+main).
      // FAV: favorite-label × 3 across all section regens (matches generateWorkout).
      const recentSet = new Set(recentLabels);
      const favSet    = new Set(favorites || []);
      // v1.2 — disfavor: 0.25× pick weight, mutex with favorite at DB layer.
      const disfavorSet = new Set(disfavorites || []);
      const favBoost  = (o) => {
        if (!o.label) return 1;
        if (favSet.has(o.label))      return 3;
        if (disfavorSet.has(o.label)) return disfavorMultiplier; // v1.8: 0.25 or 0
        return 1;
      };
      const phaseSpec = phase && PHASES[phase] ? PHASES[phase] : null;
      const picked = sectionKey === "main"
        ? pickWeighted(novel, (o) => {
            let w = (o.label && recentSet.has(o.label)) ? 0.25 : 1;
            if (phaseSpec) {
              const optionZone = inferBlockZone({ section: "main", sets: o.sets, primary_zone: o.primary_zone });
              const m = phaseSpec.multipliers[optionZone];
              if (typeof m === "number") w *= m;
            }
            const prefMatches = preferredEquipMatches(o, equipment);
            if (prefMatches > 0) w *= Math.pow(2, prefMatches);
            w *= favBoost(o);
            // Gap-1 (2026-05-22) — set-level fav/disfavor on regen. Mirrors
            // mainWeight's per-set logic in generateWorkout: per-set,
            // favorite hit short-circuits disfavor (v1.13 universal rule).
            // Multiplicative across multiple matching sets within one option.
            if (Array.isArray(o.sets) && ((favoriteSetIds && favoriteSetIds.size) || (disfavorSetIds && disfavorSetIds.size))) {
              let favSetMatches = 0;
              let disSetMatches = 0;
              for (const s of o.sets) {
                if (!s.id) continue;
                if (favoriteSetIds && favoriteSetIds.has(s.id))      favSetMatches++;
                else if (disfavorSetIds && disfavorSetIds.has(s.id)) disSetMatches++;
              }
              if (favSetMatches > 0) w *= Math.pow(3, favSetMatches);
              if (disSetMatches > 0) w *= Math.pow(disfavorMultiplier, disSetMatches);
            }
            return w;
          })
        : sectionKey === "drill"
        ? pickWeighted(novel, (o) => Math.pow(2, preferredEquipMatches(o, equipment)) * favBoost(o))
        : pickWeighted(novel, favBoost);

      const NAME_BY_SECTION = {
        warmup:   "Warm-Up",
        drill:    "Drill / Pre-Main Set",
        kick:     "Kick Set",
        cooldown: "Cool-Down",
      };
      const bankBlock = sectionKey === "main"
        ? { name: `Main Set — ${picked.label}`, section: "main", ...picked }
        : { name: NAME_BY_SECTION[sectionKey], section: sectionKey, ...picked };

      // S3 — engine override per section source
      let newBlock = bankBlock;
      if (sectionSource === "engine" || sectionSource === "mix") {
        const overridden = applyEngineOverrides(
          typeId,
          { [sectionKey]: bankBlock },
          { [sectionKey]: sectionSource },
          recentEngineTemplates,
          engineDisfavorites,
          disfavorMode,
          engineFavorites,
          lanesPaceSecs,
          _usePscRegen ? _effectiveCRegen : [],
        );
        newBlock = { ...bankBlock, ...overridden[sectionKey] };
      }

      const newBlocks = blocks.map((b, i) => i === idx ? newBlock : b);
      const total = newBlocks.reduce((s, b) => s + b.totalYards, 0);

      const regenResult = { blocks: newBlocks, totalYards: total, estimatedMin: calcEstimatedMin(newBlocks), typeId };
      if (_laneFitFallback) regenResult.__laneFitFallback = [sectionKey];
      return { workout: regenResult, error: null };
    }

export function parseIntervalSecs(str) {
      if (!str) return null;
      // Explicit "no interval" markers — both the canonical sentinel and any
      // legacy / loose variant. Treated identically to unparseable: caller
      // falls back to default behavior (yd/min for time estimate, etc.).
      if (/no\s*interval/i.test(str)) return null;
      const m = str.match(/^On\s+(\d*):(\d{1,2})/i);
      if (!m) return null;
      const mins = m[1] === "" ? 0 : parseInt(m[1], 10);
      const secs = parseInt(m[2], 10);
      if (isNaN(mins) || isNaN(secs)) return null;
      return mins * 60 + secs;
    }

export function formatIntervalSecs(secs) {
      const m = Math.floor(secs / 60);
      const s = secs % 60;
      // Authored data uses the `On :SS` form for sub-minute intervals (e.g. "On :40").
      // Match that convention so edited / scaled cells don't visually diverge from
      // their authored neighbors. Math is identical either way.
      const mPart = m === 0 ? "" : String(m);
      return `On ${mPart}:${String(s).padStart(2, "0")}`;
    }

export const NO_INTERVAL_CANONICAL = "No interval — swim easy";

export function scaleInterval(intervalStr, ratio) {
      const secs = parseIntervalSecs(intervalStr);
      if (secs === null) return intervalStr;
      const scaled = Math.max(30, Math.round((secs * ratio) / 5) * 5);
      return formatIntervalSecs(scaled);
    }

export function optionViolatesPSC(option, constraints) {
      if (!option || !Array.isArray(constraints) || constraints.length === 0) return false;
      const STROKE_REGEX = {
        fly:    /\b(fly|butterfly)\b/i,
        breast: /\bbreast(?:stroke)?\b/i,
        back:   /\bback(?:stroke)?\b/i,
        free:   /\b(free(?:style)?|FREE)\b/i,
      };
      const EQ_TO_BANNED = {
        paddles:   "equip_no_paddles",
        fins:      "equip_no_fins",
        snorkel:   "equip_no_snorkel",
        kick:      "equip_no_kickboard",
        pull:      "equip_no_buoy",
      };
      const optStrokes = Array.isArray(option.strokes) ? option.strokes : [];
      const sets       = Array.isArray(option.sets)    ? option.sets    : [];
      const blob       = ((option.label || "") + " " + sets.map(s => (s.desc || "") + " " + (s.focus || "")).join(" "));
      for (const c of constraints) {
        const t = c && c.constraint_type;
        if (!t) continue;
        // Stroke exclusions — option-level: explicit strokes tag wins; fallback to text match.
        if (t === "stroke_no_fly"    && (optStrokes.includes("fly")    || STROKE_REGEX.fly.test(blob)))    return true;
        if (t === "stroke_no_breast" && (optStrokes.includes("breast") || STROKE_REGEX.breast.test(blob))) return true;
        if (t === "stroke_no_back"   && (optStrokes.includes("back")   || STROKE_REGEX.back.test(blob)))   return true;
        if (t === "stroke_no_free"   && (optStrokes.includes("free")   || STROKE_REGEX.free.test(blob)))   return true;
        // Equipment exclusions — set-level: any set with the matching eq disqualifies the whole option.
        if (t.startsWith("equip_no_")) {
          for (const s of sets) {
            if (!s.eq) continue;
            if (EQ_TO_BANNED[s.eq] === t) return true;
          }
        }
        // Paddles edge case: bank eq vocab doesn't have "paddles" — fall back to text.
        if (t === "equip_no_paddles" && /\bpaddles?\b/i.test(blob)) return true;
      }
      return false;
    }

export function optionFitsAllLanes(option, lanesPaceSecs, minRest = 5, maxRestRatio = 1.5, paceBaseline = 120) {
      if (!option || !Array.isArray(option.sets) || option.sets.length === 0) return true;
      if (!Array.isArray(lanesPaceSecs) || lanesPaceSecs.length === 0) return true;
      const validLanes = lanesPaceSecs.filter(p => typeof p === "number" && p > 0);
      if (!validLanes.length) return true;
      for (const set of option.sets) {
        const intervalSecs = parseIntervalSecs(set.interval);
        if (intervalSecs === null) continue;   // no interval → unconstrained
        const dist = set.dist;
        if (!dist || dist <= 0) continue;       // defensive: skip malformed
        // baseSwimTime at baseline pace: dist/100 yards × baseline seconds per 100
        const baseSwimTime = (dist / 100) * paceBaseline;
        for (const paceL of validLanes) {
          const swimTimeL = (paceL / paceBaseline) * baseSwimTime;
          const restL = intervalSecs - swimTimeL;
          if (restL < minRest) return false;                          // slowest lane can't finish
          if (restL > maxRestRatio * swimTimeL) return false;         // fastest lane idle
        }
      }
      return true;
    }

export const TEMPLATE_BASELINE_PACE_SECS = 120;

export const TEMPLATE_CANONICAL_DISTS = [25, 50, 75, 100, 150, 200, 300, 400, 500];

export const TEMPLATE_REST_BY_EFFORT = {
      easy:      30,  // recovery rows
      aerobic:   15,  // steady aerobic — tight enough to feel
      moderate:  15,
      strong:    20,
      threshold: 15,  // sustainable hard; not full recovery
      racePace:  60,  // full recovery for race-pace work
      sprint:    60,  // full recovery between sprints
    };

export function templateComputeInterval(distYd, effortKey) {
      const restSecs = TEMPLATE_REST_BY_EFFORT[effortKey] ?? 15;
      const swimSecs = (distYd / 100) * TEMPLATE_BASELINE_PACE_SECS;
      const total = Math.max(30, Math.round((swimSecs + restSecs) / 5) * 5);
      return formatIntervalSecs(total);
    }

export function templatePick(choices, rand = Math.random) {
      if (!choices || choices.length === 0) return null;
      return choices[Math.floor(rand() * choices.length)];
    }

export function templatePickRepShape(distChoices, budgetYd, minReps, maxReps, preference = "any", rand = Math.random) {
      const cands = [];
      for (const d of distChoices) {
        // Rep count that gets closest to budget, clamped to [min, max]
        const ideal = Math.round(budgetYd / d);
        const reps = Math.max(minReps, Math.min(maxReps, ideal));
        const total = reps * d;
        const pctOff = Math.abs(total - budgetYd) / budgetYd;
        cands.push({ dist: d, reps, total, pctOff });
      }
      // Step 1: If any candidate is in ±5% tolerance, apply preference
      // among those. This is the happy path — coach gets a sensible
      // choice with budget close to target.
      const within = cands.filter(c => c.pctOff <= 0.05);
      if (within.length) {
        if (preference === "longer") {
          within.sort((a, b) => b.dist - a.dist);
          return templatePick(within.slice(0, 2), rand);
        }
        if (preference === "shorter") {
          within.sort((a, b) => a.dist - b.dist);
          return templatePick(within.slice(0, 2), rand);
        }
        within.sort((a, b) => a.pctOff - b.pctOff);
        return templatePick(within.slice(0, Math.min(3, within.length)), rand);
      }
      // Step 2: No candidate in tolerance — preference is overridden by
      // closeness so we don't ship a 31%-off "shorter" pick when a
      // 6%-off "longer" one was available. S2's validator will catch the
      // residual and retry with a different template.
      cands.sort((a, b) => a.pctOff - b.pctOff);
      return cands[0];
    }

export function templateDefaultStroke(typeKey) {
      if (["back", "breast", "fly", "free"].includes(typeKey)) return typeKey;
      if (typeKey === "im") return "IM";
      return "free";  // distance / sprint / endurance / mixed
    }

export function templateStrokeLabel(stroke) {
      const map = {
        free: "Freestyle", back: "Backstroke", breast: "Breaststroke",
        fly: "Butterfly", IM: "IM", choice: "Choice",
      };
      return map[stroke] || stroke;
    }

export function templateRepDistChoices(typeKey, section) {
      // Section-level constraint: drills favor shorter pieces, mains longer
      if (section === "drill") return [25, 50, 75, 100];
      // Type biases
      const typeBias = {
        distance:  [100, 150, 200, 300, 400],
        endurance: [100, 150, 200, 300],
        sprint:    [25, 50, 75],
        mixed:     [50, 75, 100, 150, 200],
        free:      [50, 75, 100, 150, 200],
        back:      [50, 75, 100, 150],
        breast:    [50, 75, 100, 150],
        fly:       [25, 50, 75, 100],
        im:        [100, 200],
      };
      return typeBias[typeKey] || [50, 100, 150, 200];
    }

export const TEMPLATE_DEFINITIONS = {

      // ┌────────────────────────────────────────────────────────────┐
      // │ aerobic_volume — single row, N×D, aerobic effort           │
      // │ Coverage: 27 bank options (4.4%)                           │
      // │ Example: "12×100 — moderate aerobic (RPE 6/10)"            │
      // └────────────────────────────────────────────────────────────┘
      aerobic_volume: {
        id: "aerobic_volume",
        family: "single_row",
        applicableSections: ["main"],
        applicableTypes: ["distance", "endurance", "mixed", "free", "im"],
        labelTemplate: (slots, totalYards) =>
          `Aerobic ${slots.stroke === "IM" ? "IM " : ""}${slots.repDist}s (${totalYards} yd)`,
        generate(typeKey, section, budgetYd, rand = Math.random) {
          const stroke = templateDefaultStroke(typeKey);
          // Aerobic favors longer reps: coaches more often program 10×100
          // than 16×50 for the same yardage. Cap at 300yd (above that is
          // continuous_long_swim territory).
          const distChoices = templateRepDistChoices(typeKey, section).filter(d => d <= 300);
          const shape = templatePickRepShape(distChoices, budgetYd, 6, 12, "longer", rand);
          const effortPhrase = templatePick(
            ["moderate aerobic", "easy/moderate", "aerobic pace (RPE 6/10)", "steady aerobic"],
            rand,
          );
          const interval = templateComputeInterval(shape.dist, "aerobic");
          const totalYards = shape.total;
          const slots = { stroke, repDist: shape.dist, repCount: shape.reps, effortPhrase };
          return {
            label: this.labelTemplate(slots, totalYards),
            totalYards,
            sets: [{
              reps: shape.reps, dist: shape.dist,
              desc: `${templateStrokeLabel(stroke)} — ${effortPhrase}`,
              interval,
              focus: "Build aerobic volume at sustainable pace",
            }],
          };
        },
      },

      // ┌────────────────────────────────────────────────────────────┐
      // │ descend_ladder — single row, N×D with descend 1→N cue     │
      // │ Coverage: 19 bank options (3.1%)                           │
      // │ Example: "Descend 100s — 4×100, descend 1→4"               │
      // └────────────────────────────────────────────────────────────┘
      descend_ladder: {
        id: "descend_ladder",
        family: "single_row",
        applicableSections: ["main"],
        applicableTypes: ["distance", "endurance", "mixed", "free", "back", "breast", "fly", "im", "sprint"],
        labelTemplate: (slots, totalYards) =>
          `Descend ${slots.stroke === "IM" ? "IM " : ""}${slots.repDist}s (${totalYards} yd)`,
        generate(typeKey, section, budgetYd, rand = Math.random) {
          const stroke = templateDefaultStroke(typeKey);
          const distChoices = templateRepDistChoices(typeKey, section);
          // Descend works best with 4-8 reps. No strong preference for
          // longer/shorter — coaches descend equally happily 4×200 or 8×50.
          const shape = templatePickRepShape(distChoices, budgetYd, 4, 8, "any", rand);
          const interval = templateComputeInterval(shape.dist, "strong");
          const totalYards = shape.total;
          const slots = { stroke, repDist: shape.dist, repCount: shape.reps };
          return {
            label: this.labelTemplate(slots, totalYards),
            totalYards,
            sets: [{
              reps: shape.reps, dist: shape.dist,
              desc: `${templateStrokeLabel(stroke)} — moderate to strong, descend 1→${shape.reps}`,
              interval,
              focus: "Each rep faster than the last",
            }],
          };
        },
      },

      // ┌────────────────────────────────────────────────────────────┐
      // │ block_with_recovery — hard block + easy recovery row       │
      // │ Coverage: 107 bank options (17.4%) — largest single family │
      // │ Example: "8×100 race-pace + 1×100 easy recovery"           │
      // │                                                            │
      // │ Two-row composition. Allocates ~80% of budget to hard      │
      // │ block, ~20% to recovery row.                               │
      // └────────────────────────────────────────────────────────────┘
      block_with_recovery: {
        id: "block_with_recovery",
        family: "multi_row_composition",
        applicableSections: ["main"],
        applicableTypes: ["distance", "endurance", "mixed", "free", "back", "breast", "fly", "im", "sprint"],
        labelTemplate: (slots, totalYards) =>
          `${slots.effortAdj} ${slots.stroke === "IM" ? "IM " : ""}${slots.hardDist}s + Recovery (${totalYards} yd)`,
        generate(typeKey, section, budgetYd, rand = Math.random) {
          const stroke = templateDefaultStroke(typeKey);
          // Pick a hard effort appropriate for the type
          const effortChoices = typeKey === "sprint"
            ? [{ key: "racePace", phrase: "race pace, full recovery", adj: "Race-Pace" },
               { key: "sprint",   phrase: "strong, near race pace",   adj: "Strong" }]
            : [{ key: "threshold", phrase: "threshold pace (RPE 7-8/10)", adj: "Threshold" },
               { key: "racePace",  phrase: "race pace, focused effort",   adj: "Race-Pace" },
               { key: "strong",    phrase: "strong, sustained",           adj: "Strong" }];
          const effort = templatePick(effortChoices, rand);
          // Two-step budget allocation:
          //   1. Aim hard block at ~80% of budget (leaves room for recovery)
          //   2. Size recovery from the remainder, snapped to canonical
          // This keeps total within ±5% of budget even when the hard
          // block's discrete (dist, reps) options can't hit exactly 80%.
          const hardTarget = Math.round(budgetYd * 0.8);
          // Hard block: 4-10 reps. Sprint type prefers shorter (race-pace
          // intervals are typically 25/50/75); everything else "any".
          const hardDistChoices = templateRepDistChoices(typeKey, section);
          const hardPref = typeKey === "sprint" ? "shorter" : "any";
          const shape = templatePickRepShape(hardDistChoices, hardTarget, 4, 10, hardPref, rand);
          const hardDist = shape.dist, hardReps = shape.reps;
          const hardTotal = hardReps * hardDist;
          // Recovery: pick canonical dist closest to (budget - hardTotal).
          // Clamp to 50-300 to keep it a reasonable single-rep recovery.
          const recoveryTarget = Math.max(50, Math.min(300, budgetYd - hardTotal));
          const recoveryDist = TEMPLATE_CANONICAL_DISTS.reduce((best, d) =>
            Math.abs(d - recoveryTarget) < Math.abs(best - recoveryTarget) ? d : best, 100);
          const hardInterval = templateComputeInterval(hardDist, effort.key);
          const recoveryInterval = templateComputeInterval(recoveryDist, "easy");
          const totalYards = hardTotal + recoveryDist;
          const slots = { stroke, hardDist, hardReps, recoveryDist,
                          effortKey: effort.key, effortPhrase: effort.phrase, effortAdj: effort.adj };
          return {
            label: this.labelTemplate(slots, totalYards),
            totalYards,
            sets: [
              {
                reps: hardReps, dist: hardDist,
                desc: `${templateStrokeLabel(stroke)} — ${effort.phrase}`,
                interval: hardInterval,
                focus: `Sustain ${effort.adj.toLowerCase()} effort across all ${hardReps}`,
              },
              {
                reps: 1, dist: recoveryDist,
                desc: "Easy choice — active recovery",
                interval: recoveryInterval,
                focus: "Flush and reset",
              },
            ],
          };
        },
      },

      // ┌────────────────────────────────────────────────────────────┐
      // │ main_plus_finisher — primary block + smaller closing block │
      // │ Coverage: 64 bank options (10.4%) — second-largest family  │
      // │ Example: "8×100 threshold + 4×50 sprint finisher"          │
      // │                                                            │
      // │ Two-row composition. Allocates ~70% to primary, ~30% to    │
      // │ finisher. Finisher uses shorter dist + faster effort cue.  │
      // └────────────────────────────────────────────────────────────┘
      main_plus_finisher: {
        id: "main_plus_finisher",
        family: "multi_row_composition",
        applicableSections: ["main"],
        applicableTypes: ["distance", "endurance", "mixed", "free", "back", "breast", "fly", "im", "sprint"],
        labelTemplate: (slots, totalYards) =>
          `${slots.primaryAdj} ${slots.stroke === "IM" ? "IM " : ""}${slots.primaryDist}s + ${slots.finisherDist}s Finisher (${totalYards} yd)`,
        generate(typeKey, section, budgetYd, rand = Math.random) {
          const stroke = templateDefaultStroke(typeKey);
          const primaryTarget = Math.round(budgetYd * 0.7);
          const finisherTarget = budgetYd - primaryTarget;
          const primaryEffort = templatePick(
            [{ key: "threshold", phrase: "threshold pace (RPE 7-8/10)", adj: "Threshold" },
             { key: "strong",    phrase: "strong, sustained",            adj: "Strong" },
             { key: "racePace",  phrase: "race pace, focused",           adj: "Race-Pace" }],
            rand,
          );
          const primaryDistChoices = templateRepDistChoices(typeKey, section);
          const primaryShape = templatePickRepShape(primaryDistChoices, primaryTarget, 4, 10, "any", rand);
          // Finisher: shorter dist + faster effort. Sprint type gets "sprint" cue;
          // others step up one effort tier above primary.
          const finisherDistChoices = primaryDistChoices.filter(d => d <= primaryShape.dist);
          const finisherShape = templatePickRepShape(
            finisherDistChoices.length ? finisherDistChoices : primaryDistChoices,
            finisherTarget, 2, 6, "shorter", rand,
          );
          const finisherEffortKey = primaryEffort.key === "racePace" ? "sprint" : "racePace";
          const finisherPhrase = finisherEffortKey === "sprint" ? "ALL OUT — empty the tank" : "race pace — close fast";
          const primaryInterval = templateComputeInterval(primaryShape.dist, primaryEffort.key);
          const finisherInterval = templateComputeInterval(finisherShape.dist, finisherEffortKey);
          const totalYards = primaryShape.total + finisherShape.total;
          const slots = { stroke, primaryDist: primaryShape.dist, finisherDist: finisherShape.dist,
                          primaryAdj: primaryEffort.adj };
          return {
            label: this.labelTemplate(slots, totalYards),
            totalYards,
            sets: [
              { reps: primaryShape.reps, dist: primaryShape.dist,
                desc: `${templateStrokeLabel(stroke)} — ${primaryEffort.phrase}`,
                interval: primaryInterval,
                focus: `Sustain ${primaryEffort.adj.toLowerCase()} effort across all ${primaryShape.reps}` },
              { reps: finisherShape.reps, dist: finisherShape.dist,
                desc: `${templateStrokeLabel(stroke)} — ${finisherPhrase}`,
                interval: finisherInterval,
                focus: "Strong close after the main block" },
            ],
          };
        },
      },

      // ┌────────────────────────────────────────────────────────────┐
      // │ stroke_rotation — distinct stroke per row, equal yardage   │
      // │ Coverage: 26 bank options (4.2%)                           │
      // │ IM types do full fly/back/breast/free; mixed picks 3.      │
      // └────────────────────────────────────────────────────────────┘
      stroke_rotation: {
        id: "stroke_rotation",
        family: "multi_row_composition",
        applicableSections: ["main"],
        applicableTypes: ["im", "mixed"],
        labelTemplate: (slots, totalYards) =>
          `${slots.strokeCount}-stroke rotation ${slots.dist}s (${totalYards} yd)`,
        generate(typeKey, section, budgetYd, rand = Math.random) {
          const allStrokes = ["fly", "back", "breast", "free"];
          const strokes = typeKey === "im"
            ? allStrokes
            : [...allStrokes].sort(() => rand() - 0.5).slice(0, 3);
          const distChoices = templateRepDistChoices(typeKey, section);
          const perStrokeBudget = Math.round(budgetYd / strokes.length);
          // Wider rep range (1-8) so per-stroke budget can be hit exactly
          // even when divisor produces awkward residuals.
          const shape = templatePickRepShape(distChoices, perStrokeBudget, 1, 8, "any", rand);
          const interval = templateComputeInterval(shape.dist, "strong");
          const sets = strokes.map(s => ({
            reps: shape.reps, dist: shape.dist,
            desc: `${templateStrokeLabel(s)} — moderate to strong, smooth`,
            interval,
            focus: `Build ${s === "free" ? "freestyle" : s} feel and pace`,
          }));
          const totalYards = sets.reduce((sum, x) => sum + x.reps * x.dist, 0);
          const slots = { strokeCount: strokes.length, dist: shape.dist };
          return {
            label: this.labelTemplate(slots, totalYards),
            totalYards,
            sets,
          };
        },
      },

      // ┌────────────────────────────────────────────────────────────┐
      // │ sandwich — easy → hard → easy bookend                      │
      // │ Coverage: 25 bank options (4.1%)                           │
      // │ 3-row composition. ~15% easy each side, ~70% hard middle.  │
      // └────────────────────────────────────────────────────────────┘
      sandwich: {
        id: "sandwich",
        family: "multi_row_composition",
        applicableSections: ["main"],
        applicableTypes: ["distance", "endurance", "mixed", "free", "back", "breast", "fly", "im"],
        labelTemplate: (slots, totalYards) =>
          `${slots.hardAdj} ${slots.stroke === "IM" ? "IM " : ""}${slots.hardDist}s Sandwich (${totalYards} yd)`,
        generate(typeKey, section, budgetYd, rand = Math.random) {
          const stroke = templateDefaultStroke(typeKey);
          const easyTarget = Math.round(budgetYd * 0.15);
          const hardTarget = budgetYd - 2 * easyTarget;
          const easyDist = TEMPLATE_CANONICAL_DISTS.reduce((best, d) =>
            Math.abs(d - easyTarget) < Math.abs(best - easyTarget) && d <= 300 ? d : best, 100);
          const hardEffort = templatePick(
            [{ key: "threshold", phrase: "threshold pace (RPE 7-8/10)", adj: "Threshold" },
             { key: "racePace",  phrase: "race pace, focused",          adj: "Race-Pace" }],
            rand,
          );
          const hardDistChoices = templateRepDistChoices(typeKey, section);
          const hardShape = templatePickRepShape(hardDistChoices, hardTarget, 4, 10, "any", rand);
          const totalYards = easyDist + hardShape.total + easyDist;
          const slots = { stroke, hardDist: hardShape.dist, hardAdj: hardEffort.adj };
          return {
            label: this.labelTemplate(slots, totalYards),
            totalYards,
            sets: [
              { reps: 1, dist: easyDist,
                desc: `${templateStrokeLabel(stroke)} — easy warm-into`,
                interval: templateComputeInterval(easyDist, "easy"),
                focus: "Settle into stroke before the main block" },
              { reps: hardShape.reps, dist: hardShape.dist,
                desc: `${templateStrokeLabel(stroke)} — ${hardEffort.phrase}`,
                interval: templateComputeInterval(hardShape.dist, hardEffort.key),
                focus: `Sustain ${hardEffort.adj.toLowerCase()} across all ${hardShape.reps}` },
              { reps: 1, dist: easyDist,
                desc: "Easy choice — cool flush",
                interval: templateComputeInterval(easyDist, "easy"),
                focus: "Active recovery to close" },
            ],
          };
        },
      },

      // ┌────────────────────────────────────────────────────────────┐
      // │ repeat_unit — N identical rounds                           │
      // │ Coverage: 24 bank options (3.9%)                           │
      // │ Example: "3 rounds × 4×100"                                │
      // └────────────────────────────────────────────────────────────┘
      repeat_unit: {
        id: "repeat_unit",
        family: "multi_row_composition",
        applicableSections: ["main"],
        applicableTypes: ["distance", "endurance", "mixed", "free", "back", "breast", "fly", "im"],
        labelTemplate: (slots, totalYards) =>
          `${slots.rounds} rounds × ${slots.repsPerRound}×${slots.dist} (${totalYards} yd)`,
        generate(typeKey, section, budgetYd, rand = Math.random) {
          const stroke = templateDefaultStroke(typeKey);
          const distChoices = templateRepDistChoices(typeKey, section);
          // Try 2-4 rounds, find the (rounds, shape) combo closest to budget
          let best = null;
          for (const rounds of [2, 3, 4]) {
            const perRoundBudget = Math.round(budgetYd / rounds);
            const shape = templatePickRepShape(distChoices, perRoundBudget, 2, 6, "any", rand);
            const total = rounds * shape.total;
            const pctOff = Math.abs(total - budgetYd) / budgetYd;
            if (!best || pctOff < best.pctOff) {
              best = { rounds, shape, total, pctOff };
            }
          }
          const interval = templateComputeInterval(best.shape.dist, "strong");
          const sets = [];
          for (let i = 0; i < best.rounds; i++) {
            sets.push({
              reps: best.shape.reps, dist: best.shape.dist,
              desc: `${templateStrokeLabel(stroke)} — round ${i + 1} of ${best.rounds}, moderate to strong`,
              interval,
              focus: i === 0 ? "Set your pace on round 1" : (i === best.rounds - 1 ? "Hold pace through the final round" : "Match round 1's pace"),
            });
          }
          const slots = { stroke, dist: best.shape.dist, repsPerRound: best.shape.reps, rounds: best.rounds };
          return {
            label: this.labelTemplate(slots, best.total),
            totalYards: best.total,
            sets,
          };
        },
      },

      // ┌────────────────────────────────────────────────────────────┐
      // │ drill_progression — multi-row drill sequence              │
      // │ Coverage: 22 bank options (3.6%)                           │
      // │ Type-specific drill sets (IM order, free drills, etc.)    │
      // └────────────────────────────────────────────────────────────┘
      drill_progression: {
        id: "drill_progression",
        family: "multi_row_composition",
        applicableSections: ["main", "drill"],
        // 2026-05-22: extended applicableTypes to include the 4 workout-types
        // (distance, sprint, endurance, mixed) that previously had ZERO
        // applicable drill templates — measured at 100% drill fallback
        // before this change. drillsByType gets matching entries below.
        applicableTypes: ["im", "back", "breast", "fly", "free", "distance", "sprint", "endurance", "mixed"],
        labelTemplate: (slots, totalYards) =>
          `Drill Progression ${slots.dist}s (${totalYards} yd)`,
        generate(typeKey, section, budgetYd, rand = Math.random) {
          // Type-specific drill banks. Each entry is [stroke, drill-description].
          // First 5 keys are stroke-types (clean stroke focus); the next 4
          // are workout-types (distance/sprint/endurance map to free-heavy
          // drill blocks; mixed cycles all four strokes).
          const drillsByType = {
            im: [
              ["fly",    "Fly drill — 3-3-3 or single-arm"],
              ["back",   "Back drill — single-arm or catch-up"],
              ["breast", "Breast drill — 2 kick / 1 pull"],
              ["free",   "Free drill — catch-up or fingertip drag"],
            ],
            free: [
              ["free", "Catch-up drill — front-quadrant timing"],
              ["free", "Fingertip drag — high elbow recovery"],
              ["free", "Single-arm — full extension hold"],
            ],
            back: [
              ["back", "Single-arm back — focus on the catch"],
              ["back", "Catch-up back — clean hand entries"],
              ["back", "6-kick rotation drill"],
            ],
            breast: [
              ["breast", "2-kick / 1-pull — feel the glide"],
              ["breast", "Pull only with float kick"],
              ["breast", "Kick only with board — drive from hips"],
            ],
            fly: [
              ["fly", "3-3-3 drill — right / left / full"],
              ["fly", "Single-arm fly — control rhythm"],
              ["fly", "2-kick / 1-pull — find the rhythm"],
            ],
            distance: [
              ["free", "Catch-up — long stroke, deliberate timing"],
              ["free", "6-3-6 — kick balance into stroke rhythm"],
              ["free", "Fingertip drag — high-elbow recovery"],
              ["free", "Single-arm — full extension hold"],
            ],
            sprint: [
              ["free", "Fast-tempo build — short, quick turnover"],
              ["free", "Underwater dolphin off the wall — power"],
              ["free", "Catch acceleration — fast first 12 yd"],
            ],
            endurance: [
              ["free", "Distance per stroke — count strokes/length"],
              ["free", "Long pull — extend the glide"],
              ["free", "Bilateral breathing — symmetric balance"],
            ],
            mixed: [
              ["free",   "Free drill — catch-up"],
              ["back",   "Back drill — single-arm"],
              ["breast", "Breast drill — 2-kick / 1-pull"],
              ["fly",    "Fly drill — 3-3-3"],
            ],
          };
          const drills = drillsByType[typeKey] || drillsByType.free;
          // 25yd dist is standard for drills (3-3-3, catch-up, single-arm
          // typically authored as 25s). Include it even when the type's
          // bias excludes it. Joint search over (dist, totalReps) to hit
          // budget exactly — totalReps distributed across drills via
          // asymmetric counts (e.g., 3 drills of 25yd with budget 400 →
          // 16 total reps as 6+5+5). Asymmetric rep counts across drills
          // are standard coaching practice ("3 reps on the first one,
          // 2 on the next two").
          const drillDists = [25, 50, 75, 100];
          let best = null;
          for (const dist of drillDists) {
            // Total reps needed across all drills for exact budget match
            const idealTotalReps = budgetYd / dist;
            // Try rep counts that yield 1-6 reps per drill on average
            for (let totalReps = drills.length; totalReps <= drills.length * 6; totalReps++) {
              const total = totalReps * dist;
              const pctOff = Math.abs(total - budgetYd) / budgetYd;
              if (!best || pctOff < best.pctOff) {
                best = { dist, totalReps, total, pctOff };
              }
            }
          }
          // Distribute totalReps across drills as evenly as possible.
          // Remainder reps go to the first few drills (front-loaded).
          const baseReps = Math.floor(best.totalReps / drills.length);
          const remainderReps = best.totalReps - baseReps * drills.length;
          const repsPerDrill = drills.map((_, i) => baseReps + (i < remainderReps ? 1 : 0));
          const interval = templateComputeInterval(best.dist, "easy");
          const sets = drills.map(([s, drillDesc], i) => ({
            reps: repsPerDrill[i], dist: best.dist,
            desc: drillDesc,
            interval,
            focus: "Slow, focused on the cue — drill quality over speed",
          }));
          const totalYards = best.total;
          const slots = { dist: best.dist };
          return {
            label: this.labelTemplate(slots, totalYards),
            totalYards,
            sets,
          };
        },
      },

      // ┌────────────────────────────────────────────────────────────┐
      // │ build_within_rep — single row with within-rep escalation  │
      // │ Coverage: 19 bank options (3.1%)                           │
      // │ "Build", "negative split", or "locomotive" style.          │
      // └────────────────────────────────────────────────────────────┘
      build_within_rep: {
        id: "build_within_rep",
        family: "single_row",
        applicableSections: ["main"],
        applicableTypes: ["distance", "endurance", "mixed", "free", "back", "breast", "fly", "im"],
        labelTemplate: (slots, totalYards) =>
          `Build ${slots.stroke === "IM" ? "IM " : ""}${slots.dist}s (${totalYards} yd)`,
        generate(typeKey, section, budgetYd, rand = Math.random) {
          const stroke = templateDefaultStroke(typeKey);
          // Build needs room WITHIN a rep to escalate — require dist ≥ 75
          const distChoices = templateRepDistChoices(typeKey, section).filter(d => d >= 75);
          const shape = templatePickRepShape(
            distChoices.length ? distChoices : [100, 150, 200],
            budgetYd, 4, 8, "any", rand,
          );
          const buildStyle = templatePick(
            ["build each rep — easy first quarter to fast last quarter",
             "negative split — second half faster than first",
             "locomotive — increase pace each segment of the rep"],
            rand,
          );
          const interval = templateComputeInterval(shape.dist, "strong");
          return {
            label: this.labelTemplate({ stroke, dist: shape.dist }, shape.total),
            totalYards: shape.total,
            sets: [{
              reps: shape.reps, dist: shape.dist,
              desc: `${templateStrokeLabel(stroke)} — ${buildStyle}`,
              interval,
              focus: "Controlled escalation within each rep — finish faster than you started",
            }],
          };
        },
      },

      // ┌────────────────────────────────────────────────────────────┐
      // │ threshold_steady — single row at threshold pace            │
      // │ Coverage: 18 bank options (2.9%)                           │
      // │ Tighter intervals than aerobic_volume.                     │
      // └────────────────────────────────────────────────────────────┘
      threshold_steady: {
        id: "threshold_steady",
        family: "single_row",
        applicableSections: ["main"],
        applicableTypes: ["distance", "endurance", "mixed", "free", "im"],
        labelTemplate: (slots, totalYards) =>
          `Threshold ${slots.stroke === "IM" ? "IM " : ""}${slots.dist}s (${totalYards} yd)`,
        generate(typeKey, section, budgetYd, rand = Math.random) {
          const stroke = templateDefaultStroke(typeKey);
          const distChoices = templateRepDistChoices(typeKey, section);
          const shape = templatePickRepShape(distChoices, budgetYd, 4, 10, "any", rand);
          const interval = templateComputeInterval(shape.dist, "threshold");
          return {
            label: this.labelTemplate({ stroke, dist: shape.dist }, shape.total),
            totalYards: shape.total,
            sets: [{
              reps: shape.reps, dist: shape.dist,
              desc: `${templateStrokeLabel(stroke)} — threshold pace (RPE 7-8/10), sustainable`,
              interval,
              focus: "Hold threshold across all reps — controlled, not all out",
            }],
          };
        },
      },

      // ┌────────────────────────────────────────────────────────────┐
      // │ race_day_simulation — race-pace events + recovery between │
      // │ Coverage: 17 bank options (2.8%)                           │
      // │ Standard race distances; 2-6 events with recovery between. │
      // └────────────────────────────────────────────────────────────┘
      race_day_simulation: {
        id: "race_day_simulation",
        family: "multi_row_composition",
        applicableSections: ["main"],
        applicableTypes: ["distance", "mixed", "sprint", "im", "free"],
        labelTemplate: (slots, totalYards) =>
          `Race-Day Simulation: ${slots.eventCount}×${slots.eventDist} (${totalYards} yd)`,
        generate(typeKey, section, budgetYd, rand = Math.random) {
          const stroke = templateDefaultStroke(typeKey);
          const raceDistances = typeKey === "sprint" ? [50, 100] :
                                 typeKey === "distance" ? [200, 400, 500] :
                                 [100, 200, 400];
          // Search all (eventDist, recoveryDist, count) — previously locked
          // recovery to ~50% of event, which jumped past ±5% for some
          // (event, budget) pairs. Letting recovery flex across canonical
          // dists (25 to event_dist) closes the budget gap. Recovery is
          // capped at event_dist so it stays a "recovery" semantically
          // (longer recoveries become weird "easy main + race-pace blip").
          let best = null;
          for (const eventDist of raceDistances) {
            const recoveryOptions = TEMPLATE_CANONICAL_DISTS.filter(d => d >= 25 && d <= eventDist);
            for (const recoveryDist of recoveryOptions) {
              for (let count = 2; count <= 6; count++) {
                const total = count * eventDist + (count - 1) * recoveryDist;
                const pctOff = Math.abs(total - budgetYd) / budgetYd;
                if (!best || pctOff < best.pctOff) {
                  best = { eventDist, recoveryDist, count, total, pctOff };
                }
              }
            }
          }
          const sets = [];
          for (let i = 0; i < best.count; i++) {
            sets.push({
              reps: 1, dist: best.eventDist,
              desc: `${templateStrokeLabel(stroke)} — race pace, Event ${i + 1}`,
              interval: templateComputeInterval(best.eventDist, "racePace"),
              focus: "Race-pace simulation — hit your goal split",
            });
            if (i < best.count - 1) {
              sets.push({
                reps: 1, dist: best.recoveryDist,
                desc: "Easy choice — between events",
                interval: templateComputeInterval(best.recoveryDist, "easy"),
                focus: "Recover before the next event",
              });
            }
          }
          return {
            label: this.labelTemplate({ eventCount: best.count, eventDist: best.eventDist }, best.total),
            totalYards: best.total,
            sets,
          };
        },
      },

      // ┌────────────────────────────────────────────────────────────┐
      // │ pyramid_up_down — all reps=1, peak in middle               │
      // │ Coverage: 13 bank options (2.1%) — spec marquee template   │
      // │ Walks the canonical-distance ladder; non-uniform steps OK. │
      // └────────────────────────────────────────────────────────────┘
      pyramid_up_down: {
        id: "pyramid_up_down",
        family: "single_rep_multi_row",
        applicableSections: ["main"],
        applicableTypes: ["distance", "endurance", "mixed", "free", "back", "breast", "fly", "im", "sprint"],
        labelTemplate: (slots, totalYards) =>
          `Pyramid Up-Down ${slots.base}-${slots.peak} (${totalYards} yd)`,
        generate(typeKey, section, budgetYd, rand = Math.random) {
          const stroke = templateDefaultStroke(typeKey);
          // Type biases give an ALLOWED range for base/peak; we search the
          // (base, peak, peak-reps) space to find the pyramid total closest
          // to budget. Pyramid totals jump in big discrete steps (canonical
          // dists have non-uniform gaps), so a narrow search misses ±5%
          // tolerance often. Peak-reps ∈ {1, 2} lets us "hold the peak" for
          // a finer-grained yardage knob without breaking the pyramid shape.
          const typeBiases = {
            sprint:    { baseMin: 25, baseMax: 50,  peakMin: 75,  peakMax: 100 },
            fly:       { baseMin: 25, baseMax: 50,  peakMin: 75,  peakMax: 100 },
            back:      { baseMin: 25, baseMax: 50,  peakMin: 100, peakMax: 200 },
            breast:    { baseMin: 25, baseMax: 50,  peakMin: 100, peakMax: 200 },
            distance:  { baseMin: 50, baseMax: 150, peakMin: 200, peakMax: 400 },
            endurance: { baseMin: 50, baseMax: 100, peakMin: 150, peakMax: 300 },
            im:        { baseMin: 50, baseMax: 100, peakMin: 150, peakMax: 300 },
            mixed:     { baseMin: 25, baseMax: 100, peakMin: 100, peakMax: 300 },
            free:      { baseMin: 25, baseMax: 75,  peakMin: 100, peakMax: 200 },
          };
          const bias = typeBiases[typeKey] || { baseMin: 50, baseMax: 100, peakMin: 100, peakMax: 200 };
          const inRange = (d, lo, hi) => d >= lo && d <= hi;
          const allowedBases = TEMPLATE_CANONICAL_DISTS.filter(d => inRange(d, bias.baseMin, bias.baseMax));
          const allowedPeaks = TEMPLATE_CANONICAL_DISTS.filter(d => inRange(d, bias.peakMin, bias.peakMax));
          let best = null;
          for (const base of allowedBases) {
            const baseIdx = TEMPLATE_CANONICAL_DISTS.indexOf(base);
            for (const peak of allowedPeaks) {
              const peakIdx = TEMPLATE_CANONICAL_DISTS.indexOf(peak);
              if (peakIdx < baseIdx + 2) continue;  // need ≥3 rungs per side
              for (const peakReps of [1, 2]) {
                const dists = [];
                for (let i = baseIdx; i <= peakIdx; i++) dists.push(TEMPLATE_CANONICAL_DISTS[i]);
                if (peakReps === 2) dists.push(TEMPLATE_CANONICAL_DISTS[peakIdx]);  // hold peak
                for (let i = peakIdx - 1; i >= baseIdx; i--) dists.push(TEMPLATE_CANONICAL_DISTS[i]);
                const total = dists.reduce((s, d) => s + d, 0);
                const pctOff = Math.abs(total - budgetYd) / budgetYd;
                if (!best || pctOff < best.pctOff) {
                  best = { dists, total, pctOff, base, peak, peakReps };
                }
              }
            }
          }
          // Fallback (shouldn't fire with valid bias config)
          if (!best) {
            best = { dists: [50, 100, 150, 100, 50], total: 450, pctOff: 1, base: 50, peak: 150, peakReps: 1 };
          }
          // Peak position depends on whether we held the peak for 2 rungs
          const ascLen = best.dists.length / 2 + (best.peakReps === 2 ? 0.5 : 0);
          const sets = best.dists.map((d, i) => {
            const atPeak = best.peakReps === 2
              ? (d === best.peak && (i === Math.floor(ascLen - 0.5) || i === Math.floor(ascLen + 0.5)))
              : d === best.peak;
            return {
              reps: 1, dist: d,
              desc: atPeak
                ? `${templateStrokeLabel(stroke)} — peak rung, push hard`
                : `${templateStrokeLabel(stroke)} — ${i < ascLen ? "build up" : "descend down"} the pyramid`,
              interval: templateComputeInterval(d, "strong"),
              focus: atPeak ? "Apex — hardest rung" : "Maintain form and pace control",
            };
          });
          return {
            label: this.labelTemplate({ base: best.base, peak: best.peak }, best.total),
            totalYards: best.total,
            sets,
          };
        },
      },

      // ═══════════════════════════════════════════════════════════════
      //  S3 — Warmup + cooldown templates
      //  Per spec §11 these were originally out-of-scope for v1 ("Engine-
      //  generated warmups and cooldowns"). Cap'n's S3 choice was to
      //  enable engine for all 4 sections, which required templates for
      //  warmup + cooldown. The five below are shaped on coaching norms
      //  (warmups: 300-800yd easy/build, often no-interval; cooldowns:
      //  200-400yd easy throughout).
      // ═══════════════════════════════════════════════════════════════

      // ┌────────────────────────────────────────────────────────────┐
      // │ aerobic_warmup — single row, easy aerobic                  │
      // │ Warmup. Typical: 8×50 or 6×100 easy.                       │
      // └────────────────────────────────────────────────────────────┘
      aerobic_warmup: {
        id: "aerobic_warmup",
        family: "single_row",
        applicableSections: ["warmup"],
        applicableTypes: ["distance", "endurance", "mixed", "free", "back", "breast", "fly", "im", "sprint"],
        labelTemplate: (slots, totalYards) =>
          `Aerobic warmup ${slots.dist}s (${totalYards} yd)`,
        generate(typeKey, section, budgetYd, rand = Math.random) {
          const stroke = templateDefaultStroke(typeKey);
          // Warmup dists stay short — 50/75/100 typical, sometimes 150
          const distChoices = [50, 75, 100, 150].filter(d => d * 4 <= budgetYd * 1.5);
          const shape = templatePickRepShape(
            distChoices.length ? distChoices : [50, 75, 100],
            budgetYd, 4, 10, "any", rand,
          );
          const effortPhrase = templatePick(
            ["easy, settle in", "easy/moderate, loosen up", "aerobic pace, find your stroke"],
            rand,
          );
          return {
            label: this.labelTemplate({ dist: shape.dist }, shape.total),
            totalYards: shape.total,
            sets: [{
              reps: shape.reps, dist: shape.dist,
              desc: `${templateStrokeLabel(stroke)} — ${effortPhrase}`,
              interval: NO_INTERVAL_CANONICAL,
              focus: "Prime the aerobic engine — long stroke",
            }],
          };
        },
      },

      // ┌────────────────────────────────────────────────────────────┐
      // │ warmup_build — single row, build within rep                │
      // │ Warmup. 4×100 easy→fast over the rep.                      │
      // └────────────────────────────────────────────────────────────┘
      warmup_build: {
        id: "warmup_build",
        family: "single_row",
        applicableSections: ["warmup"],
        applicableTypes: ["distance", "endurance", "mixed", "free", "back", "breast", "fly", "im", "sprint"],
        labelTemplate: (slots, totalYards) =>
          `Build warmup ${slots.dist}s (${totalYards} yd)`,
        generate(typeKey, section, budgetYd, rand = Math.random) {
          const stroke = templateDefaultStroke(typeKey);
          // Build needs room within a rep — 75 or 100 minimum, 150 max for warmup
          const distChoices = [75, 100, 150];
          const shape = templatePickRepShape(distChoices, budgetYd, 3, 6, "any", rand);
          return {
            label: this.labelTemplate({ dist: shape.dist }, shape.total),
            totalYards: shape.total,
            sets: [{
              reps: shape.reps, dist: shape.dist,
              desc: `${templateStrokeLabel(stroke)} — build from easy to moderate across each rep`,
              interval: templateComputeInterval(shape.dist, "aerobic"),
              focus: "Progressive warm-up — finish each rep stronger than you started",
            }],
          };
        },
      },

      // ┌────────────────────────────────────────────────────────────┐
      // │ multi_stroke_warmup — N strokes, each row a different one  │
      // │ Warmup. Loosens all four strokes before mains.             │
      // └────────────────────────────────────────────────────────────┘
      multi_stroke_warmup: {
        id: "multi_stroke_warmup",
        family: "multi_row_composition",
        applicableSections: ["warmup"],
        applicableTypes: ["distance", "endurance", "mixed", "free", "back", "breast", "fly", "im", "sprint"],
        labelTemplate: (slots, totalYards) =>
          `${slots.strokeCount}-stroke warmup ${slots.dist}s (${totalYards} yd)`,
        generate(typeKey, section, budgetYd, rand = Math.random) {
          // IM types do full 4-stroke order; everyone else 3 strokes
          const allStrokes = ["fly", "back", "breast", "free"];
          const strokes = typeKey === "im"
            ? allStrokes
            : [...allStrokes].sort(() => rand() - 0.5).slice(0, 3);
          // Short pieces for warmup — 25/50/75. Joint search over (dist,
          // totalReps) with front-loaded asymmetric distribution so the
          // total can hit budget exactly even when budget/strokes.length
          // doesn't divide cleanly (e.g., 400yd / 3 strokes / canonical
          // dists). Same trick as drill_progression.
          const warmupDists = [25, 50, 75];
          let best = null;
          for (const dist of warmupDists) {
            for (let totalReps = strokes.length; totalReps <= strokes.length * 8; totalReps++) {
              const total = totalReps * dist;
              const pctOff = Math.abs(total - budgetYd) / budgetYd;
              if (!best || pctOff < best.pctOff) {
                best = { dist, totalReps, total, pctOff };
              }
            }
          }
          const baseReps = Math.floor(best.totalReps / strokes.length);
          const remainderReps = best.totalReps - baseReps * strokes.length;
          const repsPerStroke = strokes.map((_, i) => baseReps + (i < remainderReps ? 1 : 0));
          const interval = templateComputeInterval(best.dist, "easy");
          const sets = strokes.map((s, i) => ({
            reps: repsPerStroke[i], dist: best.dist,
            desc: `${templateStrokeLabel(s)} — easy, focus on stroke quality`,
            interval,
            focus: `Loosen ${s === "free" ? "freestyle" : s} mechanics`,
          }));
          const totalYards = best.total;
          const shape = { dist: best.dist };
          return {
            label: this.labelTemplate({ strokeCount: strokes.length, dist: shape.dist }, totalYards),
            totalYards,
            sets,
          };
        },
      },

      // ┌────────────────────────────────────────────────────────────┐
      // │ easy_swim_cooldown — single long easy rep                  │
      // │ Cooldown. 1×200/300/400 easy.                              │
      // └────────────────────────────────────────────────────────────┘
      easy_swim_cooldown: {
        id: "easy_swim_cooldown",
        family: "single_row",
        applicableSections: ["cooldown"],
        applicableTypes: ["distance", "endurance", "mixed", "free", "back", "breast", "fly", "im", "sprint"],
        labelTemplate: (slots, totalYards) =>
          `Easy ${slots.dist} cooldown (${totalYards} yd)`,
        generate(typeKey, section, budgetYd, rand = Math.random) {
          // Cooldown stroke: most types do freestyle; back/breast/fly/im swimmers
          // appreciate doing the off-stroke (often back) for active recovery.
          const cooldownStroke = ["back", "breast", "fly", "im"].includes(typeKey)
            ? (typeKey === "back" ? "free" : "back")  // backstrokers cool down with free; others cool down with back
            : (rand() < 0.7 ? "free" : "choice");
          // Pick canonical dist closest to budget (single rep)
          const cooldownDist = TEMPLATE_CANONICAL_DISTS.reduce((best, d) =>
            (d >= 100 && d <= 500 && Math.abs(d - budgetYd) < Math.abs(best - budgetYd)) ? d : best, 200);
          return {
            label: this.labelTemplate({ dist: cooldownDist }, cooldownDist),
            totalYards: cooldownDist,
            sets: [{
              reps: 1, dist: cooldownDist,
              desc: `${templateStrokeLabel(cooldownStroke)} — easy, fully recovered`,
              interval: NO_INTERVAL_CANONICAL,
              focus: "Active recovery — flush the system",
            }],
          };
        },
      },

      // ┌────────────────────────────────────────────────────────────┐
      // │ cooldown_descend — descending ladder, each piece easier    │
      // │ Cooldown. 200/150/100/50 type pattern.                     │
      // └────────────────────────────────────────────────────────────┘
      cooldown_descend: {
        id: "cooldown_descend",
        family: "single_rep_multi_row",
        applicableSections: ["cooldown"],
        applicableTypes: ["distance", "endurance", "mixed", "free", "back", "breast", "fly", "im", "sprint"],
        labelTemplate: (slots, totalYards) =>
          `Descending cooldown ${slots.peak}-${slots.base} (${totalYards} yd)`,
        generate(typeKey, section, budgetYd, rand = Math.random) {
          const stroke = templateDefaultStroke(typeKey);
          // Build descending ladders of varying lengths to fit budget
          // Patterns: [200, 150, 100, 50] = 500; [150, 100, 50] = 300;
          // [100, 75, 50, 25] = 250; [200, 150, 100] = 450
          const patterns = [
            [200, 150, 100, 50],
            [150, 100, 75, 50, 25],
            [100, 75, 50, 25],
            [200, 150, 100],
            [150, 100, 50],
            [100, 50, 25],
          ];
          let best = null;
          for (const p of patterns) {
            const total = p.reduce((s, d) => s + d, 0);
            const pctOff = Math.abs(total - budgetYd) / Math.max(budgetYd, 1);
            if (!best || pctOff < best.pctOff) {
              best = { dists: p, total, pctOff };
            }
          }
          const sets = best.dists.map((d, i) => ({
            reps: 1, dist: d,
            desc: `${templateStrokeLabel(stroke)} — ${i === 0 ? "easy" : "easier than the last"}`,
            interval: NO_INTERVAL_CANONICAL,
            focus: i === best.dists.length - 1 ? "Final flush" : "Bring the heart rate down",
          }));
          return {
            label: this.labelTemplate({ peak: best.dists[0], base: best.dists[best.dists.length - 1] }, best.total),
            totalYards: best.total,
            sets,
          };
        },
      },
    };

export function templateValidate(option, context) {
      const errs = [];
      if (!option) { errs.push({ code: "V0", msg: "null output" }); return errs; }
      if (!option.label) errs.push({ code: "V0", msg: "missing label" });
      if (!Array.isArray(option.sets) || option.sets.length === 0) {
        errs.push({ code: "V0", msg: "missing/empty sets" });
        return errs;
      }
      // V1: yardage within ±5% of budget
      if (context?.budgetYd) {
        const pctOff = Math.abs(option.totalYards - context.budgetYd) / context.budgetYd;
        if (pctOff > 0.05) {
          errs.push({ code: "V1", msg: `yardage ${option.totalYards} vs budget ${context.budgetYd} (${(pctOff * 100).toFixed(1)}% off)` });
        }
      }
      // Per-row checks
      for (const [i, s] of option.sets.entries()) {
        // V2: canonical distance
        if (!TEMPLATE_CANONICAL_DISTS.includes(s.dist)) {
          errs.push({ code: "V2", msg: `set[${i}] dist=${s.dist} not canonical` });
        }
        // V3: interval present + format
        if (!s.interval) {
          errs.push({ code: "V3", msg: `set[${i}] missing interval` });
        } else if (s.interval !== NO_INTERVAL_CANONICAL && !/^On \d+:\d{2}$/.test(s.interval) && !/^On :\d{2}$/.test(s.interval)) {
          errs.push({ code: "V3", msg: `set[${i}] interval malformed: ${s.interval}` });
        } else {
          // V4: interval realism — interval ≥ swim time + 5s rest at baseline pace
          const secs = parseIntervalSecs(s.interval);
          if (secs !== null) {
            const swimTime = (s.dist / 100) * TEMPLATE_BASELINE_PACE_SECS;
            if (secs < swimTime + 5) {
              errs.push({ code: "V4", msg: `set[${i}] interval ${secs}s < swim time ${Math.round(swimTime)}s + 5s rest` });
            }
          }
        }
        // V6: equipment-cue match
        const descBlob = (s.desc || "") + " " + (s.focus || "");
        if (s.eq === "pull" && !/pull|paddle|buoy/i.test(descBlob)) {
          errs.push({ code: "V6", msg: `set[${i}] eq=pull but no pull/paddle/buoy cue` });
        }
        if (s.eq === "kick" && !/kick|board/i.test(descBlob)) {
          errs.push({ code: "V6", msg: `set[${i}] eq=kick but no kick/board cue` });
        }
        // V8: focus non-empty
        if (!s.focus || s.focus.trim() === "") {
          errs.push({ code: "V8", msg: `set[${i}] empty focus` });
        }
      }
      // v2.0 — V-Lane: every set's interval fits all lane paces (rest ≥ 5s
      // for slowest lane, rest ≤ 1.5× swimTime for fastest). Only fires
      // when context.lanesPaceSecs is non-empty (single-pace generate path
      // skips this check entirely). Same math as the bank picker's
      // optionFitsAllLanes — instead of returning bool we surface specific
      // failures so the retry path knows the rule was violated.
      if (Array.isArray(context?.lanesPaceSecs) && context.lanesPaceSecs.length > 0) {
        const lanes = context.lanesPaceSecs.filter(p => typeof p === "number" && p > 0);
        if (lanes.length && !optionFitsAllLanes(option, lanes, 5, 1.5, TEMPLATE_BASELINE_PACE_SECS)) {
          errs.push({ code: "V-Lane", msg: "engine output's intervals don't fit all lane paces" });
        }
      }
      // Phase 3 PSC slice 2 — V9: engine output must not violate any active
      // swimmer constraint. Same option-level check as the bank picker's
      // step-0 filter. Retry-3 logic in generateWithRetry handles rejection.
      // Skipped when activeConstraints is empty (no overhead in the default case).
      if (Array.isArray(context?.activeConstraints) && context.activeConstraints.length > 0) {
        if (optionViolatesPSC(option, context.activeConstraints)) {
          errs.push({ code: "V9", msg: "engine output violates an active per-swimmer constraint" });
        }
      }
      return errs;
    }

export const TEMPLATE_ENGINE = {
      templates: TEMPLATE_DEFINITIONS,
      list() { return Object.keys(TEMPLATE_DEFINITIONS); },
      applicable(section, typeKey) {
        return Object.values(TEMPLATE_DEFINITIONS).filter(t =>
          t.applicableSections.includes(section) &&
          t.applicableTypes.includes(typeKey)
        );
      },
      generate(templateId, typeKey, section, budgetYd, rand) {
        const tpl = TEMPLATE_DEFINITIONS[templateId];
        if (!tpl) return null;
        if (!tpl.applicableSections.includes(section)) return null;
        if (!tpl.applicableTypes.includes(typeKey)) return null;
        return tpl.generate(typeKey, section, budgetYd, rand);
      },
      validate(option, context) {
        return templateValidate(option, context);
      },
      generateWithRetry({ templateId, typeKey, section, budgetYd, recent = [], lanesPaceSecs = null, activeConstraints = [], rand = Math.random }) {
        const attempts = [];
        const ctx = { budgetYd, typeKey, section, lanesPaceSecs, activeConstraints };
        const defaultStroke = templateDefaultStroke(typeKey);
        // Anti-repeat lookup set, keyed by `template_id:stroke`.
        // The picker (S3) passes the last 10 generated entries.
        const excluded = new Set((recent || []).map(r => `${r.template_id}:${r.stroke}`));
        // If the requested template+stroke is in the excluded set, we
        // skip directly to the "different template" leg of retry.
        const requestedExcluded = excluded.has(`${templateId}:${defaultStroke}`);
        const tryGen = (tid) => {
          const tpl = TEMPLATE_DEFINITIONS[tid];
          if (!tpl) return { option: null, errors: [{ code: "V0", msg: `unknown template ${tid}` }] };
          if (!tpl.applicableSections.includes(section)) return { option: null, errors: [{ code: "V0", msg: `${tid} not applicable to section ${section}` }] };
          if (!tpl.applicableTypes.includes(typeKey)) return { option: null, errors: [{ code: "V0", msg: `${tid} not applicable to type ${typeKey}` }] };
          const opt = tpl.generate(typeKey, section, budgetYd, rand);
          const errs = templateValidate(opt, ctx);
          return { option: opt, errors: errs };
        };
        // Attempts 1+2: original template, new slot rolls each time
        // (slot picks are randomized inside each template — calling again
        // produces a different shape). Skip if anti-repeat excluded it.
        if (!requestedExcluded) {
          for (let i = 0; i < 2; i++) {
            const r = tryGen(templateId);
            attempts.push({ templateId, errors: r.errors });
            if (r.errors.length === 0) {
              return { option: r.option, attempts, templateUsed: templateId };
            }
          }
        }
        // Attempt 3: pick a different applicable template (anti-repeat aware)
        const alternatives = Object.keys(TEMPLATE_DEFINITIONS).filter(id => {
          if (id === templateId) return false;
          const tpl = TEMPLATE_DEFINITIONS[id];
          if (!tpl.applicableSections.includes(section)) return false;
          if (!tpl.applicableTypes.includes(typeKey)) return false;
          if (excluded.has(`${id}:${defaultStroke}`)) return false;
          return true;
        });
        if (alternatives.length) {
          const altId = alternatives[Math.floor(rand() * alternatives.length)];
          const r = tryGen(altId);
          attempts.push({ templateId: altId, errors: r.errors });
          if (r.errors.length === 0) {
            return { option: r.option, attempts, templateUsed: altId };
          }
        }
        // All attempts exhausted — caller falls back to bank
        return { option: null, attempts, templateUsed: null };
      },
    };

export const YARDS_PER_METER = 1 / 0.9144;

export function snapPoolDistance(value) {
      if (value <= 0) return 0;
      if (value >= 100) return Math.round(value / 25) * 25;
      return Math.max(5, Math.round(value / 5) * 5);
    }

export function convertYardsToMeters(yards)   { return snapPoolDistance(yards * 0.9144); }

export function convertMetersToYards(meters)  { return snapPoolDistance(meters * YARDS_PER_METER); }

export function convertOptionUnits(option, fromUnit, toUnit) {
      if (fromUnit === toUnit) return option;
      const ratio = toUnit === "m" ? 0.9144 : YARDS_PER_METER;
      const distConvert = toUnit === "m" ? convertYardsToMeters : convertMetersToYards;
      const newSets = option.sets.map(s => ({
        ...s,
        dist:     distConvert(s.dist),
        interval: scaleInterval(s.interval, ratio),
      }));
      const newTotal = newSets.reduce((sum, s) => sum + (s.reps || 1) * s.dist, 0);
      return { ...option, sets: newSets, totalYards: newTotal };
    }

export function getBankOptions(kind, typeId, poolMode, ugcOverlay = null) {
      // Lesson tier (Phase 5) reuses Technique content. Its "Skill Focus" is
      // carried in the main slot but sourced from the DRILL bank so options stay
      // short enough for 200–1200yd lessons (technique main sets run too long).
      // warmup/cooldown aren't type-filtered, so the alias only matters for
      // drill/main lookups. UGC overlay never applies to lesson (not user-authored).
      if (typeId === "lesson") {
        typeId = "technique";
        if (kind === "main") kind = "drill";
      }
      const targetUnit = poolMode === "25y" ? "yd" : "m";
      const byType = (kind === "drill" || kind === "main");

      const TABLE = {
        warmup: {
          "25m": [["m", WARMUP_OPTIONS_SCM], ["m", WARMUP_OPTIONS_50M], ["yd", WARMUP_OPTIONS]],
          "50m": [["m", WARMUP_OPTIONS_50M], ["yd", WARMUP_OPTIONS]],
          "25y": [["yd", WARMUP_OPTIONS]],
        },
        cooldown: {
          "25m": [["m", COOLDOWN_OPTIONS_SCM], ["m", COOLDOWN_OPTIONS_50M], ["yd", COOLDOWN_OPTIONS]],
          "50m": [["m", COOLDOWN_OPTIONS_50M], ["yd", COOLDOWN_OPTIONS]],
          "25y": [["yd", COOLDOWN_OPTIONS]],
        },
        drill: {
          "25m": [["m", DRILL_OPTIONS_SCM], ["m", DRILL_OPTIONS_50M], ["yd", DRILL_OPTIONS]],
          "50m": [["m", DRILL_OPTIONS_50M], ["yd", DRILL_OPTIONS]],
          "25y": [["yd", DRILL_OPTIONS]],
        },
        kick: {
          "25m": [["m", KICK_OPTIONS_SCM], ["m", KICK_OPTIONS_50M], ["yd", KICK_OPTIONS]],
          "50m": [["m", KICK_OPTIONS_50M], ["yd", KICK_OPTIONS]],
          "25y": [["yd", KICK_OPTIONS]],
        },
        main: {
          "25m": [["m", MAIN_OPTIONS_SCM], ["m", MAIN_OPTIONS_50M], ["yd", MAIN_OPTIONS]],
          "50m": [["m", MAIN_OPTIONS_50M], ["yd", MAIN_OPTIONS]],
          "25y": [["yd", MAIN_OPTIONS]],
        },
      };
      const chain = TABLE[kind][poolMode];

      // Canonical chain — walk fallback list until a non-empty result.
      // Phase H Stage 2: banks are flat arrays with `types: []` + `strokes: []`
      // tags on each option (multi-tag membership). For drill/main, filter by
      // typeId across BOTH arrays so an option declaring `strokes: ["back"]` is
      // found when picker asks for typeId="back", and an option declaring
      // `types: ["distance", "sprint"]` is found in either pool. Fallback to
      // `mixed`-tagged options when the primary filter returns empty —
      // preserves the previous `data[typeId] || data.mixed` semantics.
      let canonical = [];
      for (const [unit, data] of chain) {
        let list;
        if (!byType) {
          list = data;
        } else {
          list = data.filter(o =>
            (o.types   && o.types.includes(typeId)) ||
            (o.strokes && o.strokes.includes(typeId))
          );
          if (list.length === 0 && typeId !== "mixed") {
            list = data.filter(o => o.types && o.types.includes("mixed"));
          }
        }
        if (list && list.length > 0) {
          canonical = unit === targetUnit ? list : list.map(o => convertOptionUnits(o, unit, targetUnit));
          break;
        }
      }

      // UGC overlay — exact-pool-mode only (no cross-unit fallback per
      // spec §9: per-pool-mode authoring; no auto-translate in v1).
      const overlayRows = getOverlayRowsForTuple(ugcOverlay, kind, typeId, poolMode);
      return overlayRows.length > 0 ? canonical.concat(overlayRows) : canonical;
    }

export function getOverlayRowsForTuple(ugcOverlay, kind, typeId, poolMode) {
      if (!ugcOverlay) return [];
      const KEY_MAP = {
        warmup:   { "25y": "WARMUP_OPTIONS",   "25m": "WARMUP_OPTIONS_SCM",   "50m": "WARMUP_OPTIONS_50M"   },
        cooldown: { "25y": "COOLDOWN_OPTIONS", "25m": "COOLDOWN_OPTIONS_SCM", "50m": "COOLDOWN_OPTIONS_50M" },
        drill:    { "25y": "DRILL_OPTIONS",    "25m": "DRILL_OPTIONS_SCM",    "50m": "DRILL_OPTIONS_50M"    },
        main:     { "25y": "MAIN_OPTIONS",     "25m": "MAIN_OPTIONS_SCM",     "50m": "MAIN_OPTIONS_50M"     },
      };
      const key = KEY_MAP[kind] && KEY_MAP[kind][poolMode];
      if (!key) return [];
      const data = ugcOverlay[key];
      if (!data) return [];
      if (kind === "warmup" || kind === "cooldown") {
        return Array.isArray(data) ? data : [];
      }
      // drill/main — nested by type_id OR stroke_id sub-key. Phase H Stage 2:
      // dbGetUgcOverlay projects multi-tag options into EVERY matching bucket,
      // so the "all" branch must dedup by _option_id to avoid a multi-tag
      // option appearing once per bucket in catalog browse.
      if (typeof data !== "object") return [];
      if (typeId === "all") {
        const seen = new Set();
        const out = [];
        for (const sub of Object.keys(data)) {
          if (!Array.isArray(data[sub])) continue;
          for (const opt of data[sub]) {
            const id = opt && opt._option_id;
            if (id != null) {
              if (seen.has(id)) continue;
              seen.add(id);
            }
            out.push(opt);
          }
        }
        return out;
      }
      return Array.isArray(data[typeId]) ? data[typeId] : [];
    }

export function calcEstimatedMin(blocks) {
      const FALLBACK_YD_PER_MIN = 35;
      // S4 #17 — implicit transition between sets (read board, push off, pause
      // between reps of different sets). ~10s per boundary. Round-to-round
      // transitions are NOT included here because `roundRestSecs` already
      // accounts for the planned between-rounds rest.
      const TRANSITION_SECS_PER_BOUNDARY = 10;
      let totalSecs = 0;
      let totalBoundaries = 0;
      for (const block of blocks) {
        // Section model B — dryland blocks have no swim sets/intervals; skip
        // them in the swim time estimate (their reps×sets timing is informal).
        if (!block || !Array.isArray(block.sets)) continue;
        const rounds = block.rounds || 1;
        let blockSecs = 0;
        for (const set of block.sets) {
          const secs = parseIntervalSecs(set.interval);
          if (secs !== null) {
            blockSecs += set.reps * secs;
          } else {
            blockSecs += (set.reps * set.dist / FALLBACK_YD_PER_MIN) * 60;
          }
        }
        totalSecs += blockSecs * rounds;
        if (rounds > 1) totalSecs += (rounds - 1) * (block.roundRestSecs ?? 30);
        // Within-block boundaries: (sets.length - 1) per round.
        totalBoundaries += Math.max(0, block.sets.length - 1) * rounds;
      }
      // Block-to-block boundaries: (blocks.length - 1) — once between each adjacent pair.
      totalBoundaries += Math.max(0, blocks.length - 1);
      totalSecs += totalBoundaries * TRANSITION_SECS_PER_BOUNDARY;
      return Math.round(totalSecs / 60);
    }
